local P = LoreForeverPacks.Begin("LoreForever_Voice_Female_MoreQuests2")
P.transportVersion = 1
P.transport = {}
P.transport["quest:1106"] = {
  hash = "7bf2c2",
  fullHash = "7bf2c2",
  text = "Martek the Exiled. Fizzle Brassbolts is building a new engine for his car, but he cannot make pistons hard enough to take the strain. He sends you with a letter to a great smith named Martek the Exiled, far off in a camp in the Badlands. After Salt Flat Venom, Fizzle at the Mirage Raceway explains that his new engine should make the car so fast it could fly. All his trials have failed because he cannot make pistons hard enough for the heavy stress. He knows one person who might know how: Martek the Exiled, a great smith who knows more about metal than anyone. Martek is a long way off in the Badlands, camped there with a goblin, and you carry Fizzle's letter to him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1106-98eef4735f790bceac41/1-0000.mp3", duration = 41.8481633, start = 0},
  },
}
P.transport["quest:1107"] = {
  hash = "5779f5",
  fullHash = "5779f5",
  text = "Encrusted Tail Fins. Wizzle Brassbolts at the Mirage Raceway fears the rocket car is so fast that friction will tear it apart. To protect it, he needs tail fins from the Saltscale murlocs at the Vile Reef, off the coast of Stranglethorn Vale. Wizzle calls the rocket car the fastest thing on the Shimmering Flats, and worries that friction will tear it apart. The moving parts need a coat of composite that is hard but not brittle, and able to resist salt corrosion, or the flats will eat the car away. Its key ingredient is the tail fins of the Saltscale murlocs, who live at the Vile Reef, off the coast of Stranglethorn Vale. You are asked to bring Wizzle ten of them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1107-4c8a67508f66044700d7/1-0000.mp3", duration = 40.8816327, start = 0},
  },
}
P.transport["quest:1108"] = {
  hash = "da004d",
  fullHash = "da004d",
  text = "Indurium. Martek the Exiled says the Badlands hold a wealth of metal for anyone with the nerve to get it. Indurium is said to stand up to heat and stress, and Martek wants samples to test whether it could serve Fizzle's racecar. Stonevault troggs out in the Badlands are the ones carrying flakes of it. Martek the Exiled tells you he is not out in the Badlands just to avoid company. The region holds indurium, a metal said to stand up to heat and stress, and it might do for Fizzle's car. Martek wants samples to test, and has the forge hot and waiting. The true ore is deep in Uldaman, but Stonevault troggs in the Badlands carry flakes of it now and then. Martek asks for ten. The troggs that have them roam the south-east slope of a rocky clump at Agmond's End, just south of the Valley of Fangs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1108-5f6c6c129b7b4d1b68aa/1-0000.mp3", duration = 48.0914286, start = 0},
  },
}
P.transport["quest:1111"] = {
  hash = "0c775f",
  fullHash = "0c775f",
  text = "Wharfmaster Dizzywig. Kravel Koalbeard, a dwarf at the Mirage Raceway, makes it his business to get people what they need. The gnomes there are waiting on parts that reached Ratchet a week ago, and Kravel cannot go himself. He sends you to Ratchet with his parts order for Wharfmaster Dizzywig. Kravel Koalbeard sees to it that people get the things they need. The gnomes of the Mirage Raceway are waiting on a batch of parts that reached Ratchet a week ago, and Kravel cannot make the journey himself. He asks you to do the legwork, and promises more jobs with serious profit potential if you do. Ratchet lies in the Barrens. Wharfmaster Dizzywig, a goblin, is the one to see, and Kravel says Dizzywig will probably be at the docks. You carry Kravel's Parts Order there.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1111-e982b65f3b28123746e6/1-0000.mp3", duration = 48.404898, start = 0},
  },
}
P.transport["quest:1112"] = {
  hash = "d56c07",
  fullHash = "d56c07",
  text = "Parts for Kravel. Having brought Kravel Koalbeard's parts order to Wharfmaster Dizzywig, you now carry Kravel's package back to him at the Mirage Raceway on the Shimmering Flats. Dizzywig sends a message along with it: if Kravel wants more special orders, he will have to pay his tab. Wharfmaster Dizzywig gives you a package meant for Kravel Koalbeard, who waits at the Mirage Raceway in the Shimmering Flats of Thousand Needles. Dizzywig asks you to pass on a warning with it: if Kravel hopes for more special orders, he must first pay what he owes.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1112-8d45e15831fab25148b6/1-0000.mp3", duration = 33.1232653, start = 0},
  },
}
P.transport["quest:1114"] = {
  hash = "c96cc8",
  fullHash = "c96cc8",
  text = "Delivery to the Gnomes. Kravel Koalbeard now has what he needs, and wants the Delicate Car Parts carried to Fizzle Brassbolts in the Shimmering Flats, who has waited a long time for them. Kravel admits he removed a little piece from Fizzle's order, and suggests you leave it unmentioned. Kravel Koalbeard tells you the parts are for Fizzle Brassbolts, who has been waiting a long time. Kravel confesses he took one little piece out of Fizzle's order, but feels sure it will not be missed. He calls the piece small and worthless, advises you not to bring it up, and asks you to trust him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1114-e66fb2d8bf147d5d3448/1-0000.mp3", duration = 34.5861224, start = 0},
  },
}
P.transport["quest:1115"] = {
  hash = "bd3343",
  fullHash = "bd3343",
  text = "The Rumormonger. Having done a service for the gnomes, Kravel Koalbeard now wants to do the goblins a favor. He has heard that Nazz Steamboil, the goblin racer pilot, once went by another name, and wonders whether it is a secret worth money. He sends you to Krazek of Booty Bay, who would know. Kravel Koalbeard says the goblins are next in line for a favor. Nazz Steamboil, the goblin racer pilot, once went by another name, he hears, and Kravel wonders why it changed, whether it hides a secret, and whether Nazz cares to keep it hidden. The one who would know the truth, Kravel says, is Krazek, down at the southern tip of Stranglethorn in Booty Bay. Useful information might turn a profit. Look for Krazek at the Salty Sailor Tavern.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1115-df2d99befd0a3d13f25e/1-0000.mp3", duration = 49.4497959, start = 0},
  },
}
P.transport["quest:1116"] = {
  hash = "e988b7",
  fullHash = "e988b7",
  text = "Dream Dust in the Swamp. Krazek of Booty Bay says that learning about Nazz is quite a favor. While Krazek contacts sources, you are asked to bring 10 specks of dream dust, taken from dragon whelps in the Swamp of Sorrows, for Krazek's snuff pouch. Bring it back and Krazek will give you the information you seek. Krazek tells you that learning about Nazz is a considerable favor, and that you have already come a long way from the Shimmering Flats for it. While Krazek contacts sources, you are asked to gather something. The choice falls on ten specks of dream dust, taken from dragon whelps in the Swamp of Sorrows, which Krazek would love for a snuff pouch. Once you return with it, the information is yours. Green dragons of the Swamp of Sorrows carry the dream dust. Adolescent whelps and dreaming whelps both have it, and both live in the swamp's south-western corner.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1116-4ee48388e02a4c527efd/1-0000.mp3", duration = 51.2783673, start = 0},
  },
}
P.transport["quest:1117"] = {
  hash = "206b66",
  fullHash = "206b66",
  text = "Rumors for Kravel. Krazek has found what you came for. After calling in favors, doing plenty of deducing and giving up a rare bottle of elven wine, Krazek wrote a letter about Nazz Steamboil. It is too dangerous for Krazek to use, so you carry it to Kravel Koalbeard, out on the Shimmering Flats, and you are asked not to say where it came from. Krazek tells you what the search cost: some favors were used up, a rare bottle of elven wine was parted with, and a good deal of deducing was done. The result is a letter holding some very interesting bits about Nazz Steamboil. Krazek finds it too dangerous to use, and leaves it to you to do with as you will, as long as nobody learns where it came from. It goes back to Kravel Koalbeard, out on the Shimmering Flats.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1117-2ad697ea2e14ffd95be3/1-0000.mp3", duration = 48.404898, start = 0},
  },
}
P.transport["quest:1137"] = {
  hash = "d8b18b",
  fullHash = "d8b18b",
  text = "News for Fizzle. Martek the Exiled in the Badlands has news about indurium for Fizzle Brassbolts. You carry Martek's message back to the Shimmering Flats in Thousand Needles. Martek reports that indurium stands up to heat remarkably well, and believes it suits Fizzle's pistons. Flakes will not do, though: Fizzle needs real indurium ore, dug out of the depths of Uldaman at the northern edge of the Badlands, which Martek names as the true source of indurium. Martek asks you to pass on regards and repeat all of this to Fizzle Brassbolts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1137-01537764830cde804e1d/1-0000.mp3", duration = 34.1681633, start = 0},
  },
}
P.transport["quest:1147"] = {
  hash = "b4ca8f",
  fullHash = "b4ca8f",
  text = "The Swarm Grows. Moktar Krin at Ironstone Camp says Belgrom wants the silithid pushed back into the depths they crawled out of. Moktar's own half-dead war party cannot do it, so Moktar asks you to take on the silithid at the dig site to the south. After The Swarm Grows (2), Moktar Krin says Belgrom considers the silithid a threat and wants them driven back into whatever depths they came from. Having already killed the dwarves the Explorers' League sent, Moktar now has a war party in no state to fight again, and cannot do it without help. The dig site lies to the south, and Moktar expects no more dwarves there. Searchers, hive drones and invaders are the silithid to be killed, and Moktar's party cannot leave until it is done.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1147-9c7598d64a7179a1a075/1-0000.mp3", duration = 45.6881633, start = 0},
  },
}
P.transport["quest:1175"] = {
  hash = "743509",
  fullHash = "743509",
  text = "A Bump in the Road. Trackmaster Zherin looks after the track at the Mirage Raceway, and the animals out on the Shimmering Flats have grown big enough that their numbers must be kept down before they wander onto it. You are asked to thin out Saltstone Basilisks, Crystalhides and Gazers. A basilisk once collided with a racer belonging to the goblins, the Red Thunder, and in the aftermath Kronkrider took Zherin on to look after the track. Zherin cannot say what the animals out on the Shimmering Flats are eating to get so big, only that their numbers have to be kept down, or one will stray onto the course mid-race. Clearing wreckage is bad enough, and Zherin would rather not pick it out of burnt animal parts as well.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1175-abfd286111a9d303e46a/1-0000.mp3", duration = 40.8816327, start = 0},
  },
}
P.transport["quest:1178"] = {
  hash = "99e4de",
  fullHash = "99e4de",
  text = "Goblin Sponsorship. Pozzik of the goblin racing team is waiting on a prototype fuel regulator that Gazlowe promised a few weeks ago, and it has not come. Gazlowe is usually very prompt, so Pozzik asks you to go to Ratchet and ask what happened, since the gnomes are gaining on the team. Pozzik calls the racing team the pride of goblins, and says many people help it in one way or another. Gazlowe hunts down parts from all over the world for the team, and once even came to work on one of their rigs. A few weeks ago Gazlowe said a new prototype fuel regulator would be sent, but nothing has arrived, which is unlike him. With the gnomes gaining, Pozzik asks you to go to Ratchet and ask Gazlowe about it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1178-14fb6a3030acb1b6fb20/1-0000.mp3", duration = 41.6914286, start = 0},
  },
}
P.transport["quest:1180"] = {
  hash = "c3801e",
  fullHash = "c3801e",
  text = "Goblin Sponsorship. Gazlowe is back to the matter you came about: the fuel regulator promised to Pozzik has not reached Ratchet. Revilgaz in Booty Bay said he would have it shipped over, but it may have slipped through the cracks. Gazlowe sends you to Wharfmaster Lozgil there, who can check the cargo records. Gazlowe admits he promised Pozzik a new fuel regulator and still has not received it. Revilgaz of Booty Bay said he would have it shipped over, but it may have slipped through the cracks. If so, there is not much to be done, but you can at least learn whether it left Booty Bay. Wharfmaster Lozgil, at the far northwestern end of the Booty Bay docks, can look through the cargo records.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1180-9d2965085cab734822ef/1-0000.mp3", duration = 41.1167347, start = 0},
  },
}
P.transport["quest:1181"] = {
  hash = "9d1781",
  fullHash = "9d1781",
  text = "Goblin Sponsorship. Wharfmaster Lozgil cannot help any further with the missing fuel regulator, and suggests you ask Baron Revilgaz himself. You will find the Baron at the tavern across the harbor in Booty Bay, on the top floor. Wharfmaster Lozgil tells you he cannot be of much more help in tracing the missing shipment bound for Ratchet. If you want to follow it up, he suggests you go to the Baron himself, since if anyone knows Revilgaz's business, it is Revilgaz. He waits in the tavern across the harbor, on the top floor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1181-3dfdebdc93ad0aa197ee/1-0000.mp3", duration = 30.0146939, start = 0},
  },
}
P.transport["quest:1182"] = {
  hash = "550185",
  fullHash = "550185",
  text = "Goblin Sponsorship. Baron Revilgaz tells you the Venture Company shredders at Lake Nazferiti in northern Stranglethorn have a new model fuel regulator that Pozzik could use. Foreman Cozzle has proven cleverer than the Baron expected, so Revilgaz sends you to find the blueprints. Baron Revilgaz explains that the Venture Company's shredders at Lake Nazferiti, in northern Stranglethorn, carry a new model of fuel regulator. Pozzik could take advantage of it if he had the details, but Cozzle, the foreman there, is cleverer than Revilgaz gave him credit for. You might have better luck. Revilgaz knows the blueprints are kept in Cozzle's house, almost certainly under lock and key. The Venture Company is based around Lake Nazferiti, in the vale's north-eastern corner. The key is with Foreman Cozzle in the cabin atop the oil tower, and the box holding the blueprints is in the small house near the tower's base. Revilgaz admits the gnome team out there is pretty good, and says the team needs every advantage it can find.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1182-8138c52c615d9a34a646/1-0000.mp3", duration = 60.4734694, start = 0},
  },
}
P.transport["quest:1183"] = {
  hash = "205850",
  fullHash = "205850",
  text = "Goblin Sponsorship. Baron Revilgaz has the Fuel Regulator Blueprints ready and sends them to Pozzik on the Shimmering Flats. He gives his regards and adds that Pozzik should not hesitate to ask if he ever needs anything. Baron Revilgaz says you are all set. You carry the blueprints to Pozzik, out on the Shimmering Flats, with the Baron's regards and a message: if Pozzik ever needs anything, he should not hesitate to ask. Revilgaz says he will be waiting for news that Pozzik breaks the track record.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1183-fb13521e7539414fab1d/1-0000.mp3", duration = 29.962449, start = 0},
  },
}
P.transport["quest:1184"] = {
  hash = "502a1d",
  fullHash = "502a1d",
  text = "Parts of the Swarm. Korran has a message for Belgrom Rockmaul in Orgrimmar. You are to carry word back that Moktar is serving well out in Thousand Needles, and that Korran's studies are moving along. After the cracked carapaces taken from the silithid at the Rustmaul Digsite, Korran sends you back to Belgrom Rockmaul in Orgrimmar. Tell Belgrom that Moktar is doing his bidding well out in Thousand Needles. Tell him too that Korran's studies are progressing and that he hopes to learn more soon.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1184-c1e9f1a0c3e8a9b1ee09/1-0000.mp3", duration = 28.3428571, start = 0},
  },
}
P.transport["quest:1186"] = {
  hash = "2641f4",
  fullHash = "2641f4",
  text = "The Eighteenth Pilot. Pozzik will be busy fitting the new fuel regulator into the racer designs, but suggests that you help the team further by speaking with Razzeric on the Shimmering Flats. Razzeric is the team's pilot, its eighteenth, and likes to add modifications to the racers. Pozzik says the fuel regulator is keeping him busy, but you can help the team some more by talking to Razzeric on the Shimmering Flats. Razzeric is the team's pilot, its eighteenth in fact, and likes to add little modifications of his own to the racers. Pozzik adds that Razzeric is a little off his rocker, so you should try not to seem too surprised.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1186-256b256ae6d3fbf65167/1-0000.mp3", duration = 38.3216327, start = 0},
  },
}
P.transport["quest:1365"] = {
  hash = "0ef819",
  fullHash = "0ef819",
  text = "Khan Dez'hepah. After The Kolkar of Desolace, Felgur Twocuts sets you against the Kolkar's leader, Khan Dez'hepah. Many centaur clans fight one another across Desolace, and Felgur wants the Kolkar disrupted before the clans unite. The Kolkar are only one of the centaur clans of Desolace. Many roam the dry plains, fighting and dying at one another's hands. Felgur Twocuts does not mind, because the centaur are strong and brutal, and a united centaur people would be a fierce foe for the Horde. They must be dealt with before that happens. Felgur's first move is to disrupt the Kolkar by killing their leader, Khan Dez'hepah. The Kolkar Village lies northeast of where Felgur stands, and Felgur wants the khan's head brought back.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1365-d221b057e7dca20b2617/1-0000.mp3", duration = 46.08, start = 0},
  },
}
P.transport["quest:1366"] = {
  hash = "1953ba",
  fullHash = "1953ba",
  text = "Centaur Bounty. After Khan Dez'hepah, Felgur Twocuts says the scared centaur clans must now be bled. Hunt centaur of any clan across Desolace and bring Felgur fifteen of their ears. Felgur Twocuts says that now the centaur clans have been scared, it is time to bleed them. Whenever you travel Desolace, hunt centaur. Felgur does not care which clan you hunt, only that you gather ears, fifteen of them. Thinning their numbers will weaken their resolve and put an end to any thoughts of expansion.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1366-7b37a7ef8aefae1b4171/1-0000.mp3", duration = 28.8914286, start = 0},
  },
}
P.transport["quest:1367"] = {
  hash = "23ecca",
  fullHash = "23ecca",
  text = "Magram Alliance. Gurda Wildmane proposes turning the centaur clans' hatred against them: befriend one clan and use it to learn how all of them can be beaten. Siding with the Magram means slaying their enemies the Gelkis, then speaking with the Magram spokesman Warug at the edge of Magram Village, in the southeast of Desolace. Gurda Wildmane's plan is to exploit the centaurs' hatred of each other. A single clan is chosen as ally, and what it teaches shows how to defeat every clan. Choose the Magram and you cut down the Gelkis, their foes, which wins you respect among the Magram. Once you have earned enough respect, Warug, the Magram spokesman, is waiting on the outskirts of Magram Village in southeast Desolace. Before that he has nothing to say to you. The Magram have no words for the weak and kill them instead, so he sends you off to prove your strength against many Gelkis.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1367-f616a2f6c17189609f89/1-0000.mp3", duration = 52.244898, start = 0},
  },
}
P.transport["quest:1368"] = {
  hash = "6767b3",
  fullHash = "6767b3",
  text = "Gelkis Alliance. Gurda Wildmane proposes turning the centaur clans' hatred against them: befriend one clan and use it to learn how all of them can be beaten. Siding with the Gelkis means killing their worst enemy, the Magram, then meeting Uthek the Wise, a shaman of the Gelkis, on the edge of Gelkis Village in the southwest of Desolace. Gurda Wildmane's plan is to exploit the centaurs' hatred of each other. A single clan is chosen as ally, and what it teaches shows how to defeat every clan. Choose the Gelkis and you kill the Magram, whom the Gelkis hate most, to win their respect. Once you have won their respect, Uthek the Wise, shaman of the Gelkis, is to be met on the outskirts of Gelkis Village in southwest Desolace. Before then you are not welcome there: Uthek says you tread on Gelkis earth, and friendship must be proven by killing Magram centaur. Come back once Magram blood has soaked the ground.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1368-54e2c04d12ca88f90b6e/1-0000.mp3", duration = 53.8644898, start = 0},
  },
}
P.transport["quest:1369"] = {
  hash = "c8662c",
  fullHash = "c8662c",
  text = "Broken Tears. Warug says the Gelkis foolishly believe the centaur mother, Theradras, protects them. He sends you into the cave in their village to destroy the crystals they hoard there, the tears of Theradras, and bring him three of the broken pieces. Warug scorns the Gelkis for trusting Theradras, mother of the centaur, to protect them. To him no one protects the centaur, and the Magram, being the strongest, need no protection. He sends you to the cave in the Gelkis village, where they keep a hoard of crystals called the tears of Theradras. Smash them and bring Warug three broken pieces. He will only trust you with this if you are no enemy of the Magram.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1369-7444068ff3091523653e/1-0000.mp3", duration = 38.4, start = 0},
  },
}
P.transport["quest:1370"] = {
  hash = "4d7e2b",
  fullHash = "4d7e2b",
  text = "Stealing Supplies. Uthek the Wise says meat gives the Gelkis their strength, and that the Magram keep extra stores so they can fight longer between hunts. You are sent to raid the Magram village to the east and bring back six bags of dried meat. Between wars the Gelkis hunt, because meat means strength and a full belly fights harder than an empty one. Uthek the Wise says the Magram keep spare stock to last them between hunts. Raid their village to the east, take those stores, and their strength will fail. Six bags of crudely dried meat are wanted, to be brought to Uthek at the Gelkis Village.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1370-4db10c2b44496b95794d/1-0000.mp3", duration = 35.604898, start = 0},
  },
}
P.transport["quest:1371"] = {
  hash = "dcfe3b",
  fullHash = "dcfe3b",
  text = "Gizmo for Warug. Warug, in the Magram Village, remembers a gnome who once came to Desolace with a cart of strange things. He kept a wooden human from that cart until he broke it, and now he wants a new one: an advanced target dummy. A little gnome once came to Desolace, long ago, with horses and a cart. The cart held curious things: some burned in different colors, others moved though they were not alive. Warug killed the gnome, but first the gnome made him laugh. Warug kept his favorite thing from the cart, a human made of wood that waved at him until he hit it and broke it. Now he wants a new one, an advanced target dummy, and expects it from anyone who is no enemy of the Magram.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1371-1af9231b1cc631f0a4fd/1-0000.mp3", duration = 41.5346939, start = 0},
  },
}
P.transport["quest:1373"] = {
  hash = "7acf44",
  fullHash = "7acf44",
  text = "Ongeku. Uthek the Wise of the Gelkis says you still have more to prove, and that for now the Gelkis will take on the Magram without your help. The earth has whispered to Uthek of draenethyst, and you are sent far away to the Swamp of Sorrows for a shard held by the lost one Ongeku. After Stealing Supplies, Uthek the Wise tells you that your next undertaking lies a long way off. Those who listen hear many secrets in the earth, and one Uthek has heard is of a red crystal called draenethyst, newly arrived in this land and brought from a place of flying mountains and ruling demons. A shard of it, Uthek says, will make the magic strong. The lost one Ongeku holds a shard in the Swamp of Sorrows in the Eastern Kingdoms. When you return, Uthek will look for proof that the Gelkis can still call you friend.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1373-6b965b6c0f994b3d2db4/1-0000.mp3", duration = 49.1363265, start = 0},
  },
}
P.transport["quest:1374"] = {
  hash = "973e4f",
  fullHash = "973e4f",
  text = "Khan Jehn. Following Ongeku, Uthek the Wise tells you the earth says the Magram are growing weak, and that the hour has come to slay their Khan. Uthek wants the head of Khan Jehn brought to Gelkis Village. Uthek the Wise at Gelkis Village says the earth speaks to Uthek, and it tells of the Magram growing weak. Uthek names their Khan, Jehn, as the one to strike down and asks for the head of the Magram Khan. Uthek expects you to still count as a friend of the Gelkis when you come back.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1374-42ad0c8d4e053fd50bdf/1-0000.mp3", duration = 28.1077551, start = 0},
  },
}
P.transport["quest:1375"] = {
  hash = "d9982a",
  fullHash = "d9982a",
  text = "Khan Shaka. Warug of the Magram, pleased with your help after Gizmo for Warug, now wants the head of Khan Shaka, the Khan of the Gelkis. He means to stare at it and laugh at his enemy. In Magram Village, Warug tells you that you have helped the Magram and he likes you. Now he wants you to kill Khan Shaka, the Khan of the Gelkis, and bring him the head. He says he wants to stare at it and laugh at him. He expects you to stay on good terms with the Magram.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1375-6548c9d84c069c0d7aef/1-0000.mp3", duration = 28.8130612, start = 0},
  },
}
P.transport["quest:1382"] = {
  hash = "1258eb",
  fullHash = "1258eb",
  text = "Strange Alliance. Captain Pentigast sees luck in the way the centaur clans of Desolace fight each other, since as one force they could not be stopped. The Gelkis are locked in brutal war with the Magram, so Pentigast sends you to Uthek the Wise in southwestern Desolace to seek an alliance. Captain Pentigast counts it good fortune that the centaur clans war on one another, for joined together they could not be stopped. Pentigast wants to push that edge. The Gelkis and Magram are locked in brutal war, so striking at the Magram might win the Gelkis over. Uthek the Wise can be found where the Gelkis camps begin, in the southwest of Desolace, and through her an alliance might be struck. She turns you away at first, telling you to leave and to return after killing many Magram.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1382-d0fd9a6c9f81c711ff98/1-0000.mp3", duration = 44.8261224, start = 0},
  },
}
P.transport["quest:1384"] = {
  hash = "46f722",
  fullHash = "46f722",
  text = "Raid on the Kolkar. After Strange Alliance, Uthek the Wise sends you against the Kolkar centaurs to the northeast. Kill them, take their charms, and bring ten of those charms back to Uthek. Uthek scoffs at the Kolkar centaurs for thinking their magic strong; in Uthek's view they know nothing of magic. You go northeast to the Kolkar, kill them, and take their charms. Uthek wants ten Crude Charms to throw in the fire, laughing as they burn.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1384-4f485afb4844363718ee/1-0000.mp3", duration = 26.0440816, start = 0},
  },
}
P.transport["quest:1385"] = {
  hash = "277452",
  fullHash = "277452",
  text = "Brutal Politics. Captain Pentigast believes whichever centaur clan wins the wars of Desolace will spill out and threaten the Alliance strongholds. To learn how to beat them, Pentigast wants an alliance with one clan: fight the Gelkis, win over the Magram, and speak with Warug. War rages across Desolace, centaur against centaur, and the Alliance believes the winner will spill out against its strongholds. That cannot be allowed. To learn how to beat the centaurs, Captain Pentigast says, the Alliance needs one of the clans as a friend. The Magram fight the Gelkis, so striking at the Gelkis might make the Magram weigh an alliance. Earn their favor, then go to Warug in the Magram village, in Desolace's southeast. Warug warns that to be a friend of the Magram, you must kill Gelkis.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1385-7aeea2541980dd4ea6ae/1-0000.mp3", duration = 50.8865306, start = 0},
  },
}
P.transport["quest:1386"] = {
  hash = "8a0bfb",
  fullHash = "8a0bfb",
  text = "Assault on the Kolkar. After Brutal Politics, Warug in Magram Village wants proof that you can kill Kolkar the way the Magram do. Head north and slay Kolkar centaurs, scouts and maulers. Warug sneers that the Kolkar believe themselves strong while the Magram laugh at them as they kill them. Warug wants you to prove you can kill Kolkar as the Magram do, so you head north: twelve Kolkar centaurs, twelve scouts and six maulers are to fall.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1386-aeaa8154a288695deec2/1-0000.mp3", duration = 27.5591837, start = 0},
  },
}
P.transport["quest:1387"] = {
  hash = "f9dc8f",
  fullHash = "f9dc8f",
  text = "Centaur Bounty. Corporal Melkins at Nijel's Point says every centaur clan in Desolace shares one trait, cruelty, and that peace will not come while the centaur remain. Melkins asks you to hunt them across the land and bring fifteen of their ears. At Nijel's Point, Corporal Melkins describes a centaur race split among many clans, each with a leader and plans of its own, yet alike in cruelty. Peace, Melkins says, will only come if the centaurs are removed. Wandering Desolace, you hunt centaur and take their ears. Melkins wants a great many, fifteen in all, and calls the work a service to the Alliance that brings the war's end nearer.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1387-ee60dfed4c209628c9c0/1-0000.mp3", duration = 43.4677551, start = 0},
  },
}
P.transport["quest:1394"] = {
  hash = "a80ff0",
  fullHash = "a80ff0",
  text = "Final Passage. Parqual Fintallas tells you that you have passed this test and the ones before it. You are sent back to Dorn Plainstalker in Thousand Needles, who will sense the change in you and see whether you have grown strong in mind, body and spirit, enough to be honoured for your efforts. This is the last step of the Test of Faith, the chain of trials that Dorn Plainstalker began. Dorn waits in the Weathered Nook, in a cave reached by a ramp, north of Freewind Post. Parqual Fintallas urges you to stay true to the balance you have shown throughout these trials.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1394-d3f62f0ebf4b2006ccbc/1-0000.mp3", duration = 33.28, start = 0},
  },
}
P.transport["quest:1437"] = {
  hash = "88d445",
  fullHash = "88d445",
  text = "Vahlarriel's Search. Vahlarriel Demonslayer has come to Desolace to learn what became of two missing nobles of House Malem, a Darnassian merchant family. Their father fears the worst, and the last word of the pair places them in the Stonetalon Mountains some weeks back. Vahlarriel asks you to find their wagon. Vahlarriel Demonslayer is looking for Tyranis and Dalinda Malem, whose father fears the worst and has charged Vahlarriel with doing everything possible to find them. The search has barely begun, and Vahlarriel hopes it will not keep them in Desolace long. The pair were last reported crossing the Stonetalon Mountains some weeks ago. Vahlarriel asks you to find their wagon in Desolace and to come at once when you do. Its charred remains lie there, with a chest among them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1437-a5f9cedea0f98205e852/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["quest:1438"] = {
  hash = "3a14ce",
  fullHash = "3a14ce",
  text = "Vahlarriel's Search. After the second part of Vahlarriel's Search, Vahlarriel Demonslayer sends you to look for Dalinda and Tyranis Malem, beginning at the fortress. Word of it goes to Vahlarriel's superiors in Darnassus, who worry about Tyranis's motives and want Dalinda brought home safe above all. Vahlarriel Demonslayer wants you to look for both Dalinda and Tyranis, beginning at the fortress, and return with what you learn. Vahlarriel will contact superiors in Darnassus right away. A private word follows: they worry about why Tyranis came to Desolace, and they care most that Dalinda gets home safe. As for Tyranis, they want him gauged first, before any homecoming.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1438-519b283d1d3ce83c2050/1-0000.mp3", duration = 40.8032653, start = 0},
  },
}
P.transport["quest:1439"] = {
  hash = "39631c",
  fullHash = "39631c",
  text = "Search for Tyranis. Dalinda Malem tells you the orcs slaughtered all their guards and servants before bringing her and Tyranis here. Tyranis tried to speak to them, and she cannot leave until she knows what has become of her brother. She asks you to find him and come back when his fate is known. Dalinda tells you that orcs killed every guard and servant of theirs before dragging her and Tyranis to this place. She expected to die at once, yet the orcs clearly had other designs. Tyranis tried talking to them, perhaps hoping his arcane learning would impress them, though she cannot say why. She will not escape until she knows his fate, so she asks you to find him and return when you do. He is in a building left of the fortress entrance. Dalinda dreads that Tyranis, if allowed, will seek the Burning Blade's secrets and become one of them. Power has always drawn him, as it does anyone magic seduces. To her people even studying such things is a grave crime, and she doubts she could face her family with word that his spirit toyed with that danger.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1439-dd4893b6fdb6c1771755/1-0000.mp3", duration = 62.5371429, start = 0},
  },
}
P.transport["quest:1440"] = {
  hash = "4ef3e8",
  fullHash = "4ef3e8",
  text = "Return to Vahlarriel. Dalinda Malem is ready to leave Thunder Axe Fortress. She thanks you for what you have done for her and her family, and says the time is yours to choose. You escort her out, then find Vahlarriel Demonslayer. Dalinda asks whether the time has come, and offers thanks for all you have done for her and her family, in case things do not go as hoped. If you are ready, nothing else keeps her here, and she will go when you judge the moment right. You escort her out of Thunder Axe Fortress and then find Vahlarriel Demonslayer in Desolace.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1440-95051995c63a193594b2/1-0000.mp3", duration = 32.1044898, start = 0},
  },
}
P.transport["quest:1454"] = {
  hash = "18e1f6",
  fullHash = "18e1f6",
  text = "The Karnitol Shipwreck. Kreldig Ungor tells you of Karnitol, a mage who is some kind of noble in Stormwind. Sea giants struck his ship in the northwest waters of Desolace, and he left a valuable chest behind and teleported away. The chest and what is inside are to be found. After Reclaimers' Business in Desolace, Kreldig Ungor tells you of a first order of business. It concerns Karnitol, a mage who is some kind of noble in Stormwind. Sea giants struck Karnitol's ship in the northwest waters of Desolace. Karnitol and his servants tried to carry one of his costlier chests to shore, but the giants swarmed in, and he gave up the chest and teleported himself and his servants out. The chest and its contents are to be found, then returned to Karnitol in Stormwind. It lies along the northern coastline, in the Ethel Rethor stretch.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1454-ee076b82645534d6a824/1-0000.mp3", duration = 51.7746939, start = 0},
  },
}
P.transport["quest:1455"] = {
  hash = "441f3b",
  fullHash = "441f3b",
  text = "The Karnitol Shipwreck. The chest of the mage Karnitol has been pried open, and it is completely empty. Long, deep scratches on its sides and top suggest neither man nor giant was responsible, and you return to Kreldig Ungor at Nijel's Point. You study what forced the chest open. Long, deep scratches run along its sides and top. They point to something that was neither man nor giant, and they do not look like the work of a dagger or sword. The chest is completely empty. With nothing else to be done, you close it and prepare to leave, knowing Kreldig Ungor will be disappointed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1455-689bfbb2d7276f99e4ef/1-0000.mp3", duration = 36.1012245, start = 0},
  },
}
P.transport["quest:1456"] = {
  hash = "d49eb9",
  fullHash = "d49eb9",
  text = "The Karnitol Shipwreck. Kreldig Ungor still thinks Karnitol's belongings can be found. Up the same coast, by Ranazjar Isle, the Slitherblade naga hold a place among night elf ruins that lie at the bottom of the sea, and Kreldig reckons the satchel is most likely there. Following the second part of the Karnitol shipwreck search, Kreldig Ungor tells you hope is not lost. Along the same coast but farther north, close to Ranazjar Isle, sunken night elf ruins lie on the ocean floor, and the Slitherblade naga call them home. Kreldig judges it the likeliest place for Karnitol's satchel. A Recovery Diver's Potion is provided. Kreldig figures a scouting party that came so far south had to be a strong one. So in looking for Karnitol's belongings, Kreldig would try the more powerful naga first, the tidehunters and the sea witches.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1456-2a6f41e592b78b5d5e07/1-0000.mp3", duration = 50.3379592, start = 0},
  },
}
P.transport["quest:1457"] = {
  hash = "a5e782",
  fullHash = "a5e782",
  text = "The Karnitol Shipwreck. Kreldig Ungor sends you to Ironforge with Karnitol's satchel, to put it in the hands of Roetten Stonehammer, who will pay you for the work. Kreldig Ungor tells you to carry Karnitol's things back to Roetten Stonehammer in Ironforge, who will pay you for the work. With a laugh, Kreldig adds that Roetten may be so pleased that you get asked to join the Reclaimers full time. The way back should be made carefully and without dawdling, since Karnitol has little patience, though he is a generous man.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1457-c6775e5e39c86d6b3fea/1-0000.mp3", duration = 28.9959184, start = 0},
  },
}
P.transport["quest:1458"] = {
  hash = "7d4285",
  fullHash = "7d4285",
  text = "Reagents for Reclaimers Inc.. Kreldig Ungor is gathering reagents for the gnome mage Leftwitch, who lives in Kharanos, and the Reclaimers are short-handed. He wants claws and horns from the Hatefury satyrs to the east before the rest of the list can begin. After Reclaimers' Business in Desolace, Kreldig Ungor has another job on his hands: fetching reagents for Leftwitch, the gnome mage who lives in Kharanos. Roetten reckons it is easy coin, since the Reclaimers are already out in Desolace, and Kreldig says he does not care that the crew is short-handed. The first items on the list should be simple enough. Kreldig wants ten claws and ten horns taken from the Hatefury satyrs to the east, who are found in the Sargeron ruins due east of Nijel's Point. Once he has them, the rest of the list can begin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1458-8bbafb9ebda4747deec1/1-0000.mp3", duration = 49.1363265, start = 0},
  },
}
P.transport["quest:1459"] = {
  hash = "d67682",
  fullHash = "d67682",
  text = "Reagents for Reclaimers Inc.. Next on Leftwitch's list for Kreldig Ungor is venom from the scorpashi and hides from aged kodo. Kreldig cannot say where to find either, since he does not know Desolace well. Following the first part of Leftwitch's list, Kreldig Ungor turns to the next items. They look simple enough, but the instructions are exact. The mage wants venom from the scorpashi, any of them will do, and hides from kodo, but only aged kodo. Dying and ancient kodo are no use. Kreldig wants seven vials of venom and three hides. Mages, Kreldig muses, ask for some odd things. Kreldig has no idea where the kodo and the scorpashi roam. Kreldig barely knows the area and has had no time to explore it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1459-94ce28100625c07d848b/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["quest:1465"] = {
  hash = "6c0be8",
  fullHash = "6c0be8",
  text = "Vahlarriel's Search. Going on with the search of the Malems' wagon, you turn up a pendant and a trail of footprints heading south. Smoke rises from a big fort far off. Vahlarriel Demonslayer at Nijel's Point should be shown the pendant and told about the sign that the Malems may live. Searching the wagon further, you turn up a pendant, and beyond it footprints leading south. Far off, smoke rises from a big fort. A tended fire makes it, not buildings burning, and your instincts say that if the Malems are still alive, they were taken that way. Vahlarriel Demonslayer at Nijel's Point should see the Malem Pendant, and should hear of the footprints leading south.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1465-0c97f8b0a2dabc431040/1-0000.mp3", duration = 40.5681633, start = 0},
  },
}
P.transport["quest:1480"] = {
  hash = "a76fbd",
  fullHash = "a76fbd",
  text = "The Corrupter. A piece of flayed demon skin, taken from the Burning Blade at Thunder Axe Fortress, smells rotten yet is surprisingly pliable. Red markings of some language cover one side, and at the bottom is a clear symbol that looks like a signature. Maurin Bonesplitter at Ghost Walker Post may be able to tell you more. The torn skin stinks of rot, yet it bends easily, though it seems dry and fragile. Unrolled, it carries red markings on one side, a written language of some sort. At the bottom is a plain symbol, which you take to be a signature. Maurin Bonesplitter at Ghost Walker Post may know more about the skin. Maurin holds that the Burning Blade are coming to see how weak they are, with poor magic and little strength. Whatever power they have comes from those they serve, not from any grasp of true power and knowledge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1480-52dc43f5975a0d53713c/1-0000.mp3", duration = 50.0767347, start = 0},
  },
}
P.transport["quest:1481"] = {
  hash = "8f7e23",
  fullHash = "8f7e23",
  text = "The Corrupter. Maurin Bonesplitter believes the demon lord can be found, but first any wards the creature holds against scrying must be broken. For that, Maurin wants the scalp of a Hatefury shadowstalker, hunted in the old ruins of Desolace's northeast. Maurin Bonesplitter believes the demon lord can be found, given the proper reagents. If the lord is as powerful as Maurin suspects, those must come from deadly creatures, and Maurin is sure you, acting in the Warchief's name, will take up the challenge. The first need is to break any wards the demon has against scrying. For that Maurin wants a scalp from a satyr, though only a Hatefury shadowstalker's will serve. They are to be sought in the old ruins of Desolace's northeast, near Sargeron. Maurin cautions you against bringing back the wrong scalp. The wrong reagents could get people killed, since the demon lord may carry contingency spells meant to slay anyone who tries to scry on him. Maurin adds that fate has already dealt out enough pain.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1481-17e280c150c4865a0bf7/1-0000.mp3", duration = 59.924898, start = 0},
  },
}
P.transport["quest:1482"] = {
  hash = "c0a344",
  fullHash = "c0a344",
  text = "The Corrupter. Maurin Bonesplitter wants an oracle crystal, which the naga craft for their oracles, in order to find the demon lord Azrethoc. A vast coral reef lies northwest along the coast, home to the Slitherblade naga, and they will not welcome you. Maurin Bonesplitter says an oracle crystal will do the job of finding the demon lord Azrethoc, whose signature was on the skin you brought. Naga craft such crystals, and their oracles use them. Up the coast to the northwest lies a vast coral reef which the naga have made their home while near the shore, and the oracles can be found in that place. The Slitherblade there are deadly and will take your intrusion badly, so Maurin urges you to go carefully and quickly. Maurin points out that finding and destroying Lord Azrethoc would earn both of you much favor with the Warchief. Working together, and swiftly, would serve the ends of each.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1482-8280dbc479b704c38c64/1-0000.mp3", duration = 54.0995918, start = 0},
  },
}
P.transport["quest:1484"] = {
  hash = "f0d135",
  fullHash = "f0d135",
  text = "The Corrupter. Maurin Bonesplitter has found the demon lord far more dangerous than expected. He is certain Takata Steelblade doubts his abilities, and leaving the swordsman uninformed of what happened would insult Takata's honor. Maurin sends you to speak with Takata, who is nearby. Maurin Bonesplitter finds the creature much more dangerous than he had anticipated. No doubt Takata Steelblade questions whether Maurin can handle it, and not being told of what just happened would insult Takata's honor. Maurin asks you to speak to the swordsman and offer to slay the demon, should Takata allow it. Maurin cautions you not to press Takata too hard, since it is better if Takata believes the idea is his own. Takata Steelblade is close at hand, just across the path from Maurin, on a cliff overlooking the Kodo Graveyard.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1484-09653c9a5ec5923e8444/1-0000.mp3", duration = 48.1697959, start = 0},
  },
}
P.transport["quest:185"] = {
  hash = "645680",
  fullHash = "645680",
  text = "Tiger Mastery. At the northern safari camp in Stranglethorn Vale, the hunter Ajeck Rouack offers to train adventurers in the discipline of big cat stalking. She starts newcomers against the younger tigers prowling near the camp to test basic hunting and tracking prowess. Having learned the art of hunting tigers from her father when she was a girl, Ajeck Rouack shares his craft with travelers who reach Nesingwary's Expedition following Welcome to the Jungle. She insists that tracking and slaying the youngest felines is the essential foundation before any hunter can advance to greater quarry. Young Stranglethorn tigers are often found in the jungle close to the expedition camp. Rouack demands that ten of these beasts be hunted down to prove sufficient skill before she agrees to provide any further training.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_185-da5d1bb3e1ecaa8a2678/1-0000.mp3", duration = 48.4832653, start = 0},
  },
}
P.transport["quest:186"] = {
  hash = "1efc06",
  fullHash = "1efc06",
  text = "Tiger Mastery. At Nesingwary's Expedition in northern Stranglethorn Vale, Ajeck Rouack escalates her hunting trials. Having seen your early promise with young stalkers, he now sends you into the jungle to fell mature Stranglethorn Tigers. Following your initial success against younger predators, Ajeck Rouack seeks to test your growing skills against more seasoned beasts. She directs you back out into the wilds of Stranglethorn Vale to hunt down ten mature Stranglethorn Tigers before you can pursue even greater challenges.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_186-762c3443ed24442f03b8/1-0000.mp3", duration = 30.9812245, start = 0},
  },
}
P.transport["quest:187"] = {
  hash = "5edcd8",
  fullHash = "5edcd8",
  text = "Tiger Mastery. Deep in the jungle at Nesingwary's Expedition, Ajeck Rouack raises the stakes of his hunting trials. He demands the death of ten elder Stranglethorn tigers to prove your prowess before the final test. Following the earlier hunts, Ajeck Rouack asks you to pursue ten elder Stranglethorn tigers across the wilds. He considers these beasts both the most elusive to track and the fiercest to overcome. Felling ten of them serves as the prelude to a concluding trial, after which he promises to proclaim you a master tiger hunter before Master Nesingwary.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_187-8f84dff56890ac617b90/1-0000.mp3", duration = 34.8995918, start = 0},
  },
}
P.transport["quest:188"] = {
  hash = "ab20cd",
  fullHash = "ab20cd",
  text = "Tiger Mastery. Ajeck Rouack offers the ultimate challenge in his series of hunts within northern Stranglethorn Vale. After weeks of tracking an elusive beast, he challenges you to seek out the tiger Sin'Dall and bring back her paw. Having completed the earlier trials against Stranglethorn's tigers, you are offered one last challenge by Ajeck Rouack at Nesingwary's Expedition. The hunting camp has tracked an extraordinarily elusive tiger known as Sin'Dall across the jungle for weeks. Ajeck challenges you to track her down, fell the beast, and claim her paw as indisputable proof.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_188-0122155a9a778f659353/1-0000.mp3", duration = 34.4816327, start = 0},
  },
}
P.transport["quest:189"] = {
  hash = "9dc1b0",
  fullHash = "9dc1b0",
  text = "Bloodscalp Ears. Kebok in Booty Bay is losing guards and agents to jungle clashes with the Bloodscalp tribe. Worried about climbing expenses and answering to Baron Revilgaz, he offers coin to any adventurer willing to hunt down the trolls and return with proof of the kill. In the bustling port of Booty Bay, Kebok faces a serious operational dilemma. The local trolls in Stranglethorn Vale have been killing his agents in the jungle, and he has lost many of his best guards in skirmishes with them. With the casualties mounting, so too are the costs, leaving him frantic over how to explain them to Baron Revilgaz. Rather than allowing the losses to accumulate further, Kebok turns to outside help. He offers monetary compensation to travelers who head into the jungle, cull the Bloodscalp trolls, and bring back fifteen of their severed ears as undeniable confirmation of their demise.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_189-b9adb557469a8e17a331/1-0000.mp3", duration = 53.0546939, start = 0},
  },
}
P.transport["quest:190"] = {
  hash = "ae08db",
  fullHash = "ae08db",
  text = "Panther Mastery. Sir S. J. Erlgadin of Nesingwary's Expedition offers a trial to those seeking to prove their prowess as big-game stalkers in Stranglethorn Vale. To join Hemet's hunting company, adventurers must first demonstrate their basic tracking ability by taking down ten young panthers. Within the wild expanse of northern Stranglethorn Vale, Hemet Nesingwary has assembled a seasoned band of big-game huntsmen. Sir S. J. Erlgadin tells anyone who wants a part of the hunt that they must first prove themselves an able panther hunter. Before Erlgadin entrusts anyone with greater game, he issues an entry test: finding and slaying ten young panthers. Simply finding the beasts is only half the challenge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_190-9bda93222763eeae8463/1-0000.mp3", duration = 43.7812245, start = 0},
  },
}
P.transport["quest:191"] = {
  hash = "79bc20",
  fullHash = "79bc20",
  text = "Panther Mastery. Sir S. J. Erlgadin demands that you prove yourself worthy of the big game hunters at Nesingwary's Expedition. Following your initial cull of younger beasts, he challenges you to track down and slay ten fully grown panthers in the wilds of Stranglethorn Vale. After dispatching the young panthers around the jungle, Sir S. J. Erlgadin asks you to raise your sights. To show that you deserve to keep company with seasoned big game hunters, you are sent out to hunt ten mature panthers, which are far tougher and more dangerous than their younger kin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_191-e73805c69ac5bfe91b7f/1-0000.mp3", duration = 32.4963265, start = 0},
  },
}
P.transport["quest:192"] = {
  hash = "cb4682",
  fullHash = "cb4682",
  text = "Panther Mastery. Sir S. J. Erlgadin of Nesingwary's Expedition challenges big game hunters to track and bring down the deadliest panthers in Stranglethorn Vale. Following your earlier trials, you must now seek out and slay ten Shadowmaw Panthers. Sir S. J. Erlgadin considers Shadowmaw Panthers to be the most dangerous cats prowling the jungles of Stranglethorn. Proving your mettle as a true stalker requires crawling through the dense underbrush to track down ten of these elusive beasts, whose ferocity makes them far harder to kill than to find.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_192-13dcafb497223e5da803/1-0000.mp3", duration = 34.5861224, start = 0},
  },
}
P.transport["quest:194"] = {
  hash = "355cd1",
  fullHash = "355cd1",
  text = "Raptor Mastery. At his expedition camp in northern Stranglethorn Vale, Hemet Nesingwary challenges travelers to prove their prowess in the wilderness. The famed hunter demands ten Stranglethorn Raptors slain to test whether you possess genuine hunting talent. Following your arrival in the jungle after Welcome to the Jungle, Hemet Nesingwary offers to test your tracking and hunting capabilities. Rather than handing out maps or directions, he insists that finding the Stranglethorn Raptors yourself is half the test, challenging you to venture out into the brush and bring down ten of the fierce beasts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_194-0508146a112903546cdf/1-0000.mp3", duration = 35.2914286, start = 0},
  },
}
P.transport["quest:195"] = {
  hash = "26436c",
  fullHash = "26436c",
  text = "Raptor Mastery. Deep in the jungle of Stranglethorn Vale, Hemet Nesingwary challenges hunters to step up their game against more dangerous quarry. Following an earlier raptor hunt, he directs adventurers to pursue and bring down ten Lashtail Raptors. After proving an initial measure of hunting prowess, Hemet Nesingwary expects more than idly passing time by the camp's fire. To prove true focus and skill, hunters are dispatched into the dense jungle brush just north of Grom'gol Base Camp to track down and slay ten fierce Lashtail Raptors.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_195-9fceb10dac7d0dbb6212/1-0000.mp3", duration = 34.56, start = 0},
  },
}
P.transport["quest:198"] = {
  hash = "448186",
  fullHash = "448186",
  text = "Supplies to Private Thorsen. Krazek in Booty Bay hires a courier to haul miscellaneous goblin supplies north to Lieutenant Doren's camp. Local troll aggression has halted routine shipments, requiring an outside hand to ensure the goods reach Private Thorsen near the northern border. Lieutenant Doren and his outfit stationed near the border between Stranglethorn Vale and Duskwood rely on regular shipments arranged through Krazek. Persistent attacks from local trolls have made standard delivery hazardous, prompting the goblin merchant to contract an independent courier. The package must travel all the way up the jungle road, with Private Thorsen designated to receive it either in their camp northwest of the road or along his patrol route to the south.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_198-542c421baffc15de41f6/1-0000.mp3", duration = 42.9714286, start = 0},
  },
}
P.transport["quest:200"] = {
  hash = "538986",
  fullHash = "538986",
  text = "Bookie Herod. Lieutenant Doren fears a spy among his own men after Kurzen discovered Thorsen's secret. To uncover how the secret slipped out, an investigator must infiltrate Kurzen's Compound and recover the records kept by Kurzen's logistics officer. Following the discovery of Thorsen's secret, Lieutenant Doren suspects that a traitor operates within their midst. The intelligence leak threatens their operations, and finding the traitor has become an urgent concern. Thorsen maintained a line of communication directly into Kurzen's Compound through Bookie Herod, the colonel's logistics officer. Because Herod knows how Kurzen's Compound is run from day to day, Doren believes the officer's written records hold the truth about how the operation was exposed. Reaching Bookie Herod's paperwork requires venturing into Kurzen's Compound. During Doren's time serving under Kurzen, Herod kept his office on the top floor of the compound's lone two-story house. There, among supply requisitions and missives from Colonel Kurzen himself, lie the documents that could trace how the secret was betrayed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_200-311221d63bea5c762811/1-0000.mp3", duration = 64.0783673, start = 0},
  },
}
P.transport["quest:203"] = {
  hash = "4c5f36",
  fullHash = "4c5f36",
  text = "The Second Rebellion. At the Rebel Camp in northern Stranglethorn Vale, Sergeant Yohwa seeks help against the overwhelming forces of Colonel Kurzen. Outnumbered ten to one by a cunning tactician, the rebels must rely on swift, covert strikes to survive. Cutting down Kurzen's jungle fighters is the first step toward relieving the relentless pressure on their refuge. The soldiers at the Rebel Camp face dire odds against Colonel Kurzen. Yohwa explains that the Colonel is a brilliant military tactician whose force outnumbers the rebellion by at least ten to one. Unable to wage an open war of attrition, the rebels have no choice but to adopt the Colonel's own covert tactics, launching quick incursions into his encampment to thin his ranks and escaping before heavy reinforcements can retaliate. To stem the tide, Yohwa asks you to push east into Kurzen's stronghold and eliminate a sizable contingent of his jungle fighters. Thinning out these foot soldiers eases the pressure bearing down on the Rebel Camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_203-b969220343e7b50debed/1-0000.mp3", duration = 60.16, start = 0},
  },
}
P.transport["quest:204"] = {
  hash = "4f6116",
  fullHash = "4f6116",
  text = "Bad Medicine. At the Rebel Camp in northern Stranglethorn Vale, Sergeant Yohwa seeks to blunt Colonel Kurzen's military advantage by targeting his medical support. The renegades rely on powerful remedies and toxins concocted by their practitioners, leaving the resistance fighters desperate to turn those same concoctions to their own advantage. Colonel Kurzen has bolstered his jungle force with numerous medicine men who heal his forces and poison Yohwa's fighters with venom fern extracts. To turn the tide of the conflict, Sergeant Yohwa directs adventurers into the Kurzen Compound to scavenge those vital supplies. Securing their jungle remedies will help treat wounded fighters at the Rebel Camp, while capturing a sample of their venom fern extract will enable the resistance to study the toxin and manufacture their own cures.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_204-408a0b1e35a0a362a297/1-0000.mp3", duration = 48.404898, start = 0},
  },
}
P.transport["quest:213"] = {
  hash = "182994",
  fullHash = "182994",
  text = "Hostile Takeover. Gelriz has been muscling out the moguls appointed by the trade princes and now makes a move on the most notorious pirate of all, and Baron Revilgaz will not stand for it. In response, Kebok in Booty Bay directs adventurers to steal strange blue crystals that Venture Company geologists have been finding near Lake Nazferiti. Gelriz has stepped over the line by shoving aside moguls chosen by the trade princes and making a move on the most notorious pirate of all. Baron Revilgaz refuses to permit such insolence, instructing Kebok to handle the intrusion however he sees fit. Kebok's chosen response is outright theft, targeting the strange blue stones that Venture Company mining crews have been unearthing. Venture Company geologists operating around Lake Nazferiti have taken a keen interest in these unusual crystals. Kebok wants eight samples brought back to Booty Bay, unconcerned with how they are acquired so long as they end up in his hands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_213-6aabcbd00b84741bb636/1-0000.mp3", duration = 57.0514286, start = 0},
  },
}
P.transport["quest:215"] = {
  hash = "ebbaad",
  fullHash = "ebbaad",
  text = "Jungle Secrets. After being rescued from an ambush in northern Stranglethorn Vale, Private Thorsen explains why he re-enlisted with Kurzen's men. He directs you back to the Rebel Camp so his commander can verify his covert intentions. Following his rescue, Private Thorsen admits the scene looks bad and asks to explain. He claims Lieutenant Doren ordered him to re-enlist with Colonel Kurzen's men to gather desperately needed intelligence for the rebellion. What seemed to be an opportunity to infiltrate Kurzen's Compound quickly turned disastrous, forcing Thorsen to refer you directly to Doren at the Rebel Camp for official confirmation while begging for complete discretion.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_215-7cccfaa151aba106a37d/1-0000.mp3", duration = 38.8179592, start = 0},
  },
}
P.transport["quest:261"] = {
  hash = "7d851f",
  fullHash = "7d851f",
  text = "Down the Scarlet Path. Brother Anton of the Scarlet Crusade, at Nijel's Point, says his order is at war with the Scourge, an evil that corrupts the people and infects the land. He asks you to prove your allegiance by destroying thirty undead ravagers in the Valley of Bones. Brother Anton speaks bluntly. He says the Scourge must be halted before it swallows the land and pulls the world into darkness, and the Scarlet Crusade has pledged itself to that fight. If you are with them, he wants your courage and allegiance shown by destroying thirty undead ravagers. They are found south of Anton, in the Valley of Bones. Succeed, and the Crusade will welcome you.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_261-1b3c4f650186b53299c1/1-0000.mp3", duration = 39.6016327, start = 0},
  },
}
P.transport["quest:328"] = {
  hash = "9f0280",
  fullHash = "9f0280",
  text = "The Hidden Key. Tucked away in the binding of Bookie Herod's ledgers is a small brass key alongside notes referencing a secure strongbox. Locating this container deep within the cavern complex behind Kurzen's Compound may reveal how Private Thorsen was betrayed. Searching through Bookie Herod's ledgers yields no direct mention of Private Thorsen, but it reveals something else: a small brass key concealed inside a book's binding. Scraps among the paperwork make passing mention of a secure strongbox tucked away inside the Stockpile, the cavern complex at the rear of Kurzen's Compound. Opening that container might reveal how Thorsen's cover was blown. Reaching the strongbox requires delving into the cave system behind the compound. Heavy, bronze-bound, and sturdily constructed, the chest sits among stacked crates in the cave.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_328-173c9604de5478e3b357/1-0000.mp3", duration = 51.3828571, start = 0},
  },
}
P.transport["quest:329"] = {
  hash = "33d5ee",
  fullHash = "33d5ee",
  text = "The Spy Revealed!. Inside Bookie Herod's strongbox lies a damp piece of parchment detailing the daily routines of Private Thorsen. Bearing only the initial M, this correspondence suggests an informant has embedded themselves among the rebels in northern Stranglethorn Vale. The muddy note is meant for Lieutenant Doren. Opening the strongbox reveals not just valuables, but an itinerary tracking Private Thorsen. The barely legible writing recounts his patrol routes, his companions, and his daily activities around the Rebel Camp, marked only with the signature -M. Such detailed observations could only come from someone living alongside Thorsen, pointing to a traitor within the rebel camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_329-9c93a399fa115f9e3578/1-0000.mp3", duration = 40.9861224, start = 0},
  },
}
P.transport["quest:330"] = {
  hash = "bc6782",
  fullHash = "bc6782",
  text = "Patrol Schedules. Following the discovery of an incriminating message signed only by an initial, Lieutenant Doren seeks to identify the traitor within the Rebel Camp. By cross-referencing duty rosters, duty records can reveal who shared patrol routes with Private Thorsen during the previous week. The recovered note bears only the initial M, which provides little on its own to expose the conspirator aiding the Kurzen forces. However, the author mentions sharing regular duty paths alongside Private Thorsen throughout the previous week. Lieutenant Doren directs you across the Rebel Camp to speak with Corporal Sethman, the soldier responsible for maintaining duty logs, to identify who walked alongside Thorsen.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_330-97fe566007d3ece55b77/1-0000.mp3", duration = 43.4677551, start = 0},
  },
}
P.transport["quest:331"] = {
  hash = "1ec895",
  fullHash = "1ec895",
  text = "Report to Doren. After obtaining the patrol information, Corporal Sethman directs you back to Lieutenant Doren. Delivering these findings brings crucial military intelligence directly to the rebels' commander in northern Stranglethorn Vale. Corporal Sethman reminds you that Lieutenant Doren wants a direct report on the patrol information. You must bring what you learned back to Doren.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_331-fff340000183478c0c09/1-0000.mp3", duration = 21.5510204, start = 0},
  },
}
P.transport["quest:349"] = {
  hash = "05c5e3",
  fullHash = "05c5e3",
  text = "Stranglethorn Fever. Deep within Stranglethorn Vale, Witch Doctor Unbagwa claims to know how to draw out the beast known as Mokk the Savage. Before communion with the spirits can begin, the witch doctor requires a Gorilla Fang as an offering. Once the ritual commences, defending the troll from agitated jungle beasts is necessary to lure the creature forth. Witch Doctor Unbagwa possesses the ritual knowledge needed to summon Mokk the Savage out of the surrounding jungle. To begin the incantation, the witch doctor demands a Gorilla Fang. Communing with the spirits carries a heavy risk, as the ritual chant draws the attention of other gorilla beasts in the vicinity, demanding protection while the magic does its work.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_349-b9178abfd47e8b60f918/1-0000.mp3", duration = 43.4416327, start = 0},
  },
}
P.transport["quest:503"] = {
  hash = "d6f8f4",
  fullHash = "d6f8f4",
  text = "Gol'dir. Krusk has gone through the documents you procured and concludes that Gol'dir is kept in a big Syndicate base up north, quite possibly in the Alterac Mountains. Gol'dir has languished in captivity far too long and needs to be freed. Krusk, in Tarren Mill, has gone through the documents you brought back after Infiltration. They point to Gol'dir being kept in a big Syndicate base up north, quite possibly in the Alterac Mountains. Krusk says the captivity has dragged on far too long and Gol'dir needs to be freed. Gol'dir is held in the top room of the inn at Strahnbrad, and the inn is packed with Syndicate. A Rusted Iron Key opens the lock, and Jailor Borhuin carries it; Borhuin may be in any building of the town.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_503-f6c4b0325de1c061f287/1-0000.mp3", duration = 45.1395918, start = 0},
  },
}
P.transport["quest:506"] = {
  hash = "6069cb",
  fullHash = "6069cb",
  text = "Blackmoore's Legacy. Gol'dir, freed from the Syndicate, has information for Krusk in Tarren Mill. The Syndicate's leader, Aliden Perenolde, visited Gol'dir and spoke of making slaves of the orcs who stand against him, and brought a girl named Elysa who wore the pendant the Warchief desires. A day or two ago, the head of the Syndicate paid Gol'dir a visit. His name was Aliden Perenolde, and he styled himself lord of the land. He confided that he meant to enslave the orcs who resisted him, just as his father and the despised Blackmoore, his mentor, once planned. Gol'dir sends you to bring this to Krusk in Tarren Mill, and will make his own way after settling his business where he is. More important, Perenolde brought his mistress, a slight girl named Elysa. Around her neck hung the pendant the Warchief desires.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_506-88125aa69164596b2c2a/1-0000.mp3", duration = 48.1697959, start = 0},
  },
}
P.transport["quest:518"] = {
  hash = "b86022",
  fullHash = "b86022",
  text = "The Crown of Will. In Tarren Mill, Melisara wants the Crushridge ogres thinned out before any real blow is struck against Mug'Thol, whose ogres now hold the Ruins of Alterac. You are sent to cut down Crushridge maulers. Mug'Thol and the Crushridge ogres have taken the Ruins of Alterac. Melisara says it will be hard to punish Mug'Thol while so many ogres stand around. First their numbers must be reduced, and only after that will the next move be made. Your part is to hunt the Crushridge maulers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_518-5794747b35a0aad50efb/1-0000.mp3", duration = 29.8840816, start = 0},
  },
}
P.transport["quest:533"] = {
  hash = "f88cc3",
  fullHash = "f88cc3",
  text = "Infiltration. In Tarren Mill, Krusk at last hears word and rumor of Gol'dir, an orc held prisoner by the Syndicate. The humans keep moving their captive about, so Krusk has narrowed the search to the Syndicate's large camp, just to the north of town, and wants you to bring back whatever information you can find. Krusk has begun to hear word and rumor of Gol'dir. The Syndicate's humans keep moving the orc about, but the search is narrowing to their large camp, just to the north of Tarren Mill. Krusk sends you there to lay hands on whatever information you can and carry it back. Krusk fears that with each day Gol'dir's prospects darken.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_533-c09d4f588511d8a75937/1-0000.mp3", duration = 40.0979592, start = 0},
  },
}
P.transport["quest:5361"] = {
  hash = "a9831f",
  fullHash = "a9831f",
  text = "Family Tree. Cliffwatcher Longhorn asks you to carry a report to Nataka Longhorn, Cliffwatcher's brother, who is stationed in Desolace. Word of unusual centaur activity is meant to reach Ghost Walker Post. Nataka, Cliffwatcher's brother, holds a posting at Ghost Walker Post in Desolace. A year has passed since Cliffwatcher last wrote, and in that time the centaurs have been behaving unusually. Nataka should hear of it, and you are asked to carry the report. The way runs to Stonetalon Mountain, which lies north of the Crossroads, then west into the Charred Vale. From there it turns south into Desolace, where a road runs south to Ghost Walker Post.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5361-153a4440c4fb9f4791cf/1-0000.mp3", duration = 42.6318367, start = 0},
  },
}
P.transport["quest:5381"] = {
  hash = "0684db",
  fullHash = "0684db",
  text = "Hand of Iruxos. Taiga Wisemane in Shadowprey Village says the Burning Blade holds a Demon Box, and that something powerful called the Hand of Iruxos is kept inside. At Mannoroc Coven, the Burning Blade makes use of it to open demon portals. Taiga sends you to Thunder Axe Fortress to fetch the box. Taiga Wisemane wants the flow of demons into our world stopped. You are given a demon pick, to be used on the red crystal inside Thunder Axe Fortress, which opens the way to the Demon Box. The box and the pick are to be brought back to Taiga in Shadowprey Village.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5381-d5ce081d5d77d2169cea/1-0000.mp3", duration = 35.3697959, start = 0},
  },
}
P.transport["quest:5386"] = {
  hash = "3cec1a",
  fullHash = "3cec1a",
  text = "Catch of the Day. Cooked fish has not been smelled at Ghost Walker Post for a long time, and Nataka Longhorn would like that to change. Nataka rates the trolls of Shadowprey Village as the finest fish-catchers around, yet all the centaur activity leaves little time for the journey. You are asked to go in Nataka's place and bring back two Bloodbelly fish. No cooked fish has been smelled at Ghost Walker Post for a long while. Nataka Longhorn rates the trolls of Shadowprey Village as the finest fish-catchers, but with so much centaur activity there is little time to make the journey. So you are asked to go there, talk with the local fisherman Jinar'Zillen, and return with two Bloodbelly fish, Nataka's favorite. The road south of the post bends west and brings you to the troll village.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5386-cf16b6f2a61ad22fcc55/1-0000.mp3", duration = 47.0465306, start = 0},
  },
}
P.transport["quest:540"] = {
  hash = "b2f250",
  fullHash = "b2f250",
  text = "Preserving Knowledge. Loremaster Dibbs in Southshore sends you into the Ruins of Alterac, where ogres have settled among the precious books left behind. Tomes the ogres looted must be recovered, and one above all: a worn leather book holding The Arm of Gri'lek, a work of ancient troll lore. Ogres have made their home in the ruins of Alterac, and Dibbs dreads what they might be doing to the books still there. You are to go in, hunt for the tomes the ogres have looted, and recover whatever you can. Dibbs would search the ruins too, but fears old bones would not survive the climb into the mountains. Among all the tomes, Dibbs most wants one book: the worn leather volume containing The Arm of Gri'lek. Dibbs is bent on learning the ancient troll lore inside, and the Ruins of Alterac were the last known home of an intact copy.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_540-899baf9cbcb018ff4fb2/1-0000.mp3", duration = 50.7297959, start = 0},
  },
}
P.transport["quest:5421"] = {
  hash = "0f270f",
  fullHash = "0f270f",
  text = "Fish in a Bucket. Jinar'Zillen of Shadowprey Village in Desolace likes to do as little as possible. Many shellfish traps sit below the village docks, and anyone who gathers the shellfish from them will be repaid with something worth having. Jinar'Zillen keeps many shellfish traps below the docks of Shadowprey Village, and would far rather someone else did the collecting. Anyone willing to take on that work is promised something they want in return: one fine Bloodbelly fish for every five shellfish brought in.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5421-06b743fab5f43e0e5721/1-0000.mp3", duration = 29.1526531, start = 0},
  },
}
P.transport["quest:544"] = {
  hash = "d59e02",
  fullHash = "d59e02",
  text = "Prison Break In. Magus Wordeen Voidglare is in Tarren Mill on research but now faces a crisis. A few months ago four Forsaken fled the Undercity after stealing artifacts from a secure vault, and Sylvanas wants them back. Voidglare came to Tarren Mill to research and now must resolve a crisis. Four Forsaken turned their backs on their brethren and, worse, stole from the Dark Lady. They broke into a secure vault and took four artifacts the apothecaries required for certain studies. Sylvanas wants them returned. The thieves ran from the Undercity to Dalaran, where the wizards put them in quarantine at the Lordamere Internment Camp. You are to find the traitors, take back the artifacts and report to Voidglare in Tarren Mill. There are four: a Bloodstone Wedge, Marble, Shard and Oval. Dermot has the wedge, Ricter the marble, Alina the shard and Kegan Darkmar the oval.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_544-96175fbf88affe522e12/1-0000.mp3", duration = 54.7265306, start = 0},
  },
}
P.transport["quest:545"] = {
  hash = "60999b",
  fullHash = "60999b",
  text = "Dalaran Patrols. Magus Wordeen Voidglare in Tarren Mill cares nothing for why the wizards of Dalaran raised a great dome of magic over their city's heart. What matters is that the ruined outskirts beyond the dome may conceal treasures of real magical worth, while the wizards and their elemental slaves patrol the area. Voidglare wants those patrols thinned. After Prison Break In, Voidglare turns to the wizards of Dalaran, who raised a great dome of magic over their city's heart. Some say it shelters them from the violence of the age; others say they simply wanted solitude to study and plot. Voidglare does not care which. The ruined outskirts beyond the dome may conceal treasures of real magical worth, but the wizards and their elemental slaves patrol the area. You are to hunt six Dalaran Summoners and twelve Elemental Slaves, then return to Voidglare in Tarren Mill.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_545-bb6284d916ba94eae922/1-0000.mp3", duration = 53.7861224, start = 0},
  },
}
P.transport["quest:5501"] = {
  hash = "a91851",
  fullHash = "a91851",
  text = "Bone Collector. At Kormek's Hut in Desolace, the goblin Bibbly F'utzbuckle is certain that kodo bones are about to transform the world. Ten of them are wanted from the Kodo Graveyard, south of the hut, and something is promised in return. Bibbly insists the hut is sitting on a goldmine. Customers make furniture, musical instruments and even blasting powder from kodo bones. Bibbly sends you south to the Kodo Graveyard to bring back ten of them, with something promised in return. A caravan comes by to pick up Bibbly's kodo bones, then sells them at Shadowprey Village. It is due any moment, and Bibbly is ten bones short of what is called a career high.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5501-6ddb8417a12b230733ca/1-0000.mp3", duration = 40.5681633, start = 0},
  },
}
P.transport["quest:552"] = {
  hash = "6dfefc",
  fullHash = "6dfefc",
  text = "Helcular's Revenge. Novice Thaivand in Tarren Mill means to avenge Master Helcular, a great wizard on the brink of becoming a lich, who was killed by a human lynch mob after it found his ritual lair. Before vengeance can fall on Southshore, Thaivand needs Helcular's Rod, which one of the yeti there must hold. Master Helcular was on the brink of becoming a lich when he was found and killed by a human lynch mob, who had discovered the ritual lair he kept in the hills. They then buried the body in the Southshore cemetery. His apprentice, Thaivand, finds this disregard for a great wizard unacceptable and vows that the rains of vengeance will fall upon the town of Southshore. Thaivand says Helcular's Rod is needed first. Yeti have overtaken the ritual lair, and Thaivand is sure one of the beasts has the rod. There are so many yeti in the region that finding it will be difficult. Growless Cave and Darrow Hill are among the places they can be found.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_552-9a04779d06b968fd3c95/1-0000.mp3", duration = 57.5216327, start = 0},
  },
}
P.transport["quest:553"] = {
  hash = "738bd9",
  fullHash = "738bd9",
  text = "Helcular's Revenge. Novice Thaivand hands you the Rod of Helcular. Three ceremonial pyres that Helcular fashioned for his most powerful spell must each charge it, and then it is to be driven into Helcular's grave in Southshore. Helcular fashioned three ceremonial pyres for his most powerful spell, and the rod must be charged from each one. The flames of Azel and Veraz lie within the Foothill Caverns, in the yeti cave at Darrow Hill. The third, the Flame of Uzel, is found in a small cave above the caverns, farther north in the mountains, near Growless Cave. Once the rod is charged from all three flames, it is to be driven into Helcular's grave at Southshore, a heavily guarded human town. The graveyard sits in the northeast corner of the town, by the river, and the grave lies at the graveyard's southeastern corner.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_553-1178a6a06c0619d8062c/1-0000.mp3", duration = 52.48, start = 0},
  },
}
P.transport["quest:5561"] = {
  hash = "194c36",
  fullHash = "194c36",
  text = "Kodo Roundup. At Scrabblescrew's Camp in Desolace, Smeed Scrabblescrew is expecting a caravan and wants five tamed kodos ready for it. You carry Smeed's kodo kombobulator out among the ancient, aged and dying kodos, and lead the ones it tames back to the camp. Bibbly believes no other goblin in Desolace knows how to turn a profit. Smeed Scrabblescrew disagrees: the one caravan willing to brave this land depends on Smeed, and Smeed has formed a partnership with Cork and Rigger. The caravan is due at the camp shortly. Smeed built a device that can rejuvenate and bring under control aged and dying kodos. Aimed at an ancient, aged or dying kodo, it jolts the beast into a tamed kodo that follows you. You bring five of them back to Scrabblescrew's Camp, along with the device.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5561-7e410f4ce62ea2a492b7/1-0000.mp3", duration = 47.6995918, start = 0},
  },
}
P.transport["quest:557"] = {
  hash = "89cd9b",
  fullHash = "89cd9b",
  text = "Bracers of Binding. Keeper Bel'varil in Tarren Mill says the Magus, busy with the stone tokens you gathered, will eventually want their counterpart: bracers of binding. You are to collect four Bracers of Earth Binding from elementals among the ruins of Dalaran. While the Magus studies the stone tokens you gathered, Bel'varil expects a further wish: samples of the matching piece, bracers of binding. Worn on an elemental's wrists, they tie it to a mage's service. Among the ruins of Dalaran, elementals wear them. Bel'varil wants four Bracers of Earth Binding brought to Tarren Mill.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_557-132cf17ef7593a0d90b0/1-0000.mp3", duration = 36.6497959, start = 0},
  },
}
P.transport["quest:5581"] = {
  hash = "5b74da",
  fullHash = "5b74da",
  text = "Portals of the Legion. After Hand of Iruxos, Taiga Wisemane in Shadowprey Village shows you the Hand and asks you to banish six demon portals at Mannoroc Coven, warning you to be wary of the portal guardians. Taiga Wisemane holds up the Hand of Iruxos, a grisly thing to look at, and says you must carry it if the demon portals around Mannoroc Coven are ever to be closed. The demon threat is increasing, and shutting the portals will check the number of demons crossing into this world. She wants all six portals banished, and she warns you to be wary of their guardians.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5581-efecfee21f7440b19995/1-0000.mp3", duration = 33.3844898, start = 0},
  },
}
P.transport["quest:564"] = {
  hash = "7a72c4",
  fullHash = "7a72c4",
  text = "Costly Menace. Darren Malvew of Southshore hates losing the town's beautiful horses. Undead, the Syndicate gang and assorted scoundrels have cost plenty, but Darren says nothing threatens them more than the mountain lions that keep coming down from the hills of Alterac. Darren Malvew of Southshore cannot stand losing the beautiful horses there. Quite a few have been lost to undead creeps, the Syndicate gang and the scoundrels poking about the region. By Darren's own word, though, no menace to the horses is bigger than the mountain lions up in Alterac, forever coming down from the hills. Darren wants the lions dealt with: eight Mountain Lions and ten Hulking Mountain Lions. Mountain Lions are found in the lower hills of the Alterac Mountains.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_564-168a9d205e0ff848701d/1-0000.mp3", duration = 45.5314286, start = 0},
  },
}
P.transport["quest:568"] = {
  hash = "c8026a",
  fullHash = "c8026a",
  text = "The Defense of Grom'gol. Commander Aggro'gosh seeks to safeguard the Horde's foothold in Stranglethorn Vale and protect their supply chain to Stonard. To keep that supply chain safe, he directs Horde champions to thin out the Lashtail Raptors outside Grom'gol Base Camp. At Grom'gol Base Camp, Commander Aggro'gosh carries the duty of protecting every member of the Horde within the jungle. The camp exists to keep supplies flowing safely to Stonard, but some of the local inhabitants are standing in the way. The raptors outside Grom'gol are the ones in the way. Aggro'gosh calls upon loyal fighters to thin out the Lashtail Raptors there, then report back to him for reassignment.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_568-7b2b86b77677baf731ea/1-0000.mp3", duration = 39.0530612, start = 0},
  },
}
P.transport["quest:569"] = {
  hash = "652bc8",
  fullHash = "652bc8",
  text = "The Defense of Grom'gol. Commander Aggro'gosh seeks to safeguard Grom'gol's supply lines through Stranglethorn Vale. After the earlier hunt thinning the raptors outside the camp, a band of ogres encamped at the nearby Mizjah Ruins continues to harass supply caravans heading toward Stonard. The Horde's presence in northern Stranglethorn Vale is centered on supplying Stonard, an outpost of vital strategic interest. While Commander Aggro'gosh did not arrive with the intention of fighting every native group, a band of local Mosh'Ogg ogres has claimed the Mizjah Ruins southeast of the camp. Warnings have failed to stop their continuous raids against Horde supply shipments, prompting the commander to order a strike against the ogre brutes and witch doctors holding the ruins.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_569-169f132113d078635def/1-0000.mp3", duration = 43.284898, start = 0},
  },
}
P.transport["quest:570"] = {
  hash = "047e80",
  fullHash = "047e80",
  text = "Mok'thardin's Enchantment. Far Seer Mok'thardin seeks to harness the natural magic of Stranglethorn Vale for the benefit of the Horde. Building upon his previous rituals at Grom'gol Base Camp, he asks for sharp claws and a pristine feline fang to weave a powerful enchantment. Within Grom'gol Base Camp, Far Seer Mok'thardin works to understand and bend the feral power of the wild to strengthen the Horde. Having seen success in his initial rites, he promises to craft a specialized enchanted relic for those willing to brave the dense underbrush and stalk the deadly predators prowling the surrounding territory. The ritual demands eight claws taken from shadowmaw panthers and a pristine fang from a tigress. Mok'thardin notes that while these fierce felines wander across Stranglethorn Vale, a gathering of them prowls south-eastward, just past the river running by the Mizjah Ruins.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_570-941760101bf4eeb326a0/1-0000.mp3", duration = 52.8979592, start = 0},
  },
}
P.transport["quest:574"] = {
  hash = "54a2bc",
  fullHash = "54a2bc",
  text = "Special Forces. Following the reduction of the rogue colonel's rank-and-file soldiers, Sergeant Yohwa asks you to target the elite core of the compound. You are sent into the Stockpile cave to eliminate the commandos and headshrinkers before reporting to Lieutenant Doren. With the regular soldiers of the Kurzen Compound diminished through the work of the Second Rebellion, Sergeant Yohwa sets her sights on the colonel's elite specialists. She knows many of Kurzen's troops personally and calls them skilled, loyal and cruel. When they are not out in the wilderness slaughtering rebel soldiers, they are found in a cave at the back of the compound called the Stockpile. To break their strength, you are sent into the cavern to dispatch ten Kurzen Commandos and six Kurzen Headshrinkers. After the fight, Sergeant Yohwa tells you to report to her commanding officer, Lieutenant Doren, at the Rebel Camp, who will want your account firsthand.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_574-11d6c7737abacbab5f71/1-0000.mp3", duration = 51.3044898, start = 0},
  },
}
P.transport["quest:5741"] = {
  hash = "c00089",
  fullHash = "c00089",
  text = "Sceptre of Light. Azore Aldamort has heard that the Burning Blade of Thunder Axe Fortress, to the east, now hold the Sceptre of Light, which word says they obtained from the naga. Legend says it could sink whole cities beneath the great seas, and Azore will not let the Burning Blade keep such power. You are asked to bring it back to Ethel Rethor. Word has it that the naga's Sceptre of Light has come into the hands of the Burning Blade at Thunder Axe Fortress. Legend says it can sink whole cities beneath the great seas. Azore Aldamort holds that the Burning Blade cannot be allowed such power. A Burning Blade seer keeps the sceptre and studies it from the top of one of the fortress watchtowers. Azore wants you to take it from there yourself and carry it back to the tower at Ethel Rethor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5741-6bdd83cac8220791c3b6/1-0000.mp3", duration = 43.6767347, start = 0},
  },
}
P.transport["quest:5763"] = {
  hash = "ac60b1",
  fullHash = "ac60b1",
  text = "Hunting in Stranglethorn. Roon Wildmane, a tauren in Desolace, once hunted beside a dwarf named Hemet. Now Roon sends you off with a kodo horn, bound for Hemet Nesingwary in Stranglethorn, north of Grom'gol Base Camp. Long ago a dwarf named Hemet came to Desolace, eager to hunt great beasts. Hemet handled a rifle with uncanny skill, and the two hunters passed many days together, the old enmity between their peoples set aside. When Hemet went off to Stranglethorn, Roon vowed to welcome Hemet back one day for another hunt, and Roon decides that time has arrived. You are to carry Roon's kodo horn to Hemet, who will know whose it is. Look in Stranglethorn, north of Grom'gol Base Camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5763-4a808fc6de4e66bb77a8/1-0000.mp3", duration = 44.7216327, start = 0},
  },
}
P.transport["quest:578"] = {
  hash = "88d99a",
  fullHash = "88d99a",
  text = "The Stone of the Tides. Following rumours of a haunted isle off the jungle coast, Baron Revilgaz suspects an ancient troll relic has resurfaced. He directs explorers to scout the mysterious landmass and delivers a pass to research the artifact within the archives of Stormwind. Having learned of strange apparitions and water elementals haunting an offshore island in Stranglethorn Vale, Baron Revilgaz sees an opportunity. Suspecting that the goblin mage Gazban may have uncovered the fabled Stone of the Tides, the ruler of Booty Bay sends you to locate the island and confirm whether the rumors are true. To satisfy any curiosity about the relic, he provides a library scrip redeemable among the scholars in Stormwind.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_578-372fd9a9171e452c40d8/1-0000.mp3", duration = 42.9714286, start = 0},
  },
}
P.transport["quest:581"] = {
  hash = "5a61d7",
  fullHash = "5a61d7",
  text = "Hunt for Yenniku. Nimboya has returned from Orgrimmar to the jungles of Stranglethorn Vale to search for Yenniku, the youngest son of his chieftain. Suspecting the Bloodscalp tribe holds the youth captive, the scout asks you to hunt their warriors and take their tusks to demonstrate your strength. At Grom'gol Base Camp, Nimboya speaks of a grim fate looming over Yenniku, the youngest son of the Darkspear chieftain. In accordance with an old tribal custom, the boy had been placed among the Gurubashi trolls of Zul'Gurub. When the Darkspear tribe departed their homeland alongside the orc warchief Thrall, Yenniku was left behind and lost. Sent back from distant Orgrimmar, Nimboya has undertaken the responsibility of finding the chieftain's son and bringing him to safety. Nimboya believes the Bloodscalp tribe now holds Yenniku. He demands proof that an adventurer is strong enough to hunt them. You are directed north to hunt Bloodscalp trolls and gather nine of their tusks. Bringing these trophies back to Grom'gol Base Camp proves your martial prowess and begins a longer pursuit to locate the chieftain's boy, leading directly into the hunt known as Headhunting.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_581-b4c3d9ac2f5cfbf68dc9/1-0000.mp3", duration = 71.3404082, start = 0},
  },
}
P.transport["quest:582"] = {
  hash = "3d7952",
  fullHash = "3d7952",
  text = "Headhunting. Nimboya at Grom'gol Base Camp needs to determine whether Yenniku, the son of the Darkspear chieftain, is dead. Adventurers are asked to hunt Bloodscalp headhunters and recover their shrunken heads so Nimboya can examine them. Following the search begun in Hunt for Yenniku, Nimboya worries that the chieftain's son may have already perished at the hands of the Bloodscalp tribe. To find out, he asks you to hunt the Bloodscalp Headhunters roaming the ruins of Zuuldaia and Zul'Kunda up the northern coast. By gathering twenty shrunken heads from them, Nimboya hopes to inspect the grisly trophies and confirm whether Yenniku met a violent end, cursing the Bloodscalp chief Gan'zulah if the youth was indeed slain.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_582-9384511edc49285d3fa9/1-0000.mp3", duration = 43.7812245, start = 0},
  },
}
P.transport["quest:5821"] = {
  hash = "6f3244",
  fullHash = "6f3244",
  text = "Bodyguard for Hire. Cork Gizelton and Rigger would normally lead their kodo past the Kolkar centaur village, yet they stop whenever the centaur war drums are heard. Cork asks you to protect the caravan past the Kolkar village, and payment is waiting with Smeed Scrabblescrew, a bit down the road. Cork Gizelton and Rigger would normally take their kodo straight past the Kolkar centaur. Now and then the centaur war drums are heard, and the caravan stops, because dead traders make no profit. Cork asks you to guard the caravan past the Kolkar village, a short distance, and keep it in one piece. The caravan waits north of the Kolkar Village and southeast of Thunder Axe Fortress. Payment waits with Smeed Scrabblescrew at Scrabblescrew's Camp, a bit down the road. Smeed does a little business with the Gizelton caravan.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5821-f6aaf5f2f551b8cdcb3b/1-0000.mp3", duration = 49.9983673, start = 0},
  },
}
P.transport["quest:583"] = {
  hash = "45175e",
  fullHash = "45175e",
  text = "Welcome to the Jungle. Barnil Stonepot welcomes newcomers arriving at the hunting camp in northern Stranglethorn Vale. Recognizing a fellow battle-tested wanderer, he arranges an introduction to the expedition's leader, the renowned huntsman Hemet Nesingwary. Barnil Stonepot greets newcomers at the camp in the jungle of Stranglethorn Vale, and he can tell a seasoned combatant when he sees one. He points out Hemet Nesingwary, a famous Alliance war hero and peerless tracker. Nesingwary reserves his fellowship for proven veterans, and Barnil believes the old marksman might be convinced to share his hunting wisdom with someone who has endured the trials of battle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_583-43817c3c78b27c4b60e4/1-0000.mp3", duration = 38.0081633, start = 0},
  },
}
P.transport["quest:5943"] = {
  hash = "46936f",
  fullHash = "46936f",
  text = "Gizelton Caravan. Rigger Gizelton and Cork launched their caravan to get rich, and found the trade more dangerous than they expected. Mannoroc Coven lies ahead, and Rigger wants a capable adventurer to guard the caravan past it. Rigger Gizelton and Cork set up the caravan to make a fortune, and had no idea how risky turning a profit could be. Mannoroc Coven lies ahead. The demons usually leave the caravan alone, but this time the kodos are spooked. Rigger offers payment if you protect the caravan past the coven. Once it is safely through, your pay waits with Smeed, a business associate of theirs, at Scrabblescrew's Camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5943-ec85cd0f4f9ec57161f5/1-0000.mp3", duration = 39.68, start = 0},
  },
}
P.transport["quest:596"] = {
  hash = "43b04b",
  fullHash = "43b04b",
  text = "Bloody Bone Necklaces. Kin'weelay at Grom'gol Base Camp has his own agenda in Stranglethorn Vale beyond assisting Nimboya. He seeks to weaken the rival Bloodscalp tribe by gathering trophies from their warriors. Though Kin'weelay arrived in the jungle outpost of Grom'gol Base Camp to help Nimboya, he maintains private purposes of his own. The Bloodscalp trolls dwelling to the north are enemies of the Darkspears. Kin'weelay believes that claiming personal trophies from fallen foes bestows spiritual power over them, asking travelers to hunt Bloodscalp warriors and take the bloody bone necklaces they wear around their necks.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_596-cd400687af8f40d49bbd/1-0000.mp3", duration = 36.8065306, start = 0},
  },
}
P.transport["quest:601"] = {
  hash = "618900",
  fullHash = "618900",
  text = "Water Elementals. Following discoveries regarding the Stone of the Tides, Baron Revilgaz seeks a way to counteract the artifact's curse. He sends adventurers back to the island to harvest bracers from conjured water elementals so their magical residue can be inspected by experts. Believing the water elementals were summoned by the goblin wizard Gazban, Baron Revilgaz suspects their magical residue holds clues to dealing with the Stone of the Tides. The stone is said to curse anyone who wields it, causing the bearer to drift in and out of reality. To find a countermeasure, Revilgaz directs you back to the island off the coast to gather elemental bracers that might be scrutinized by the scholarly mages of Dalaran. Upon receiving the bracers, Revilgaz admits he lacks the specialized expertise to tell whether any of them will be of use. Rather than travel to Dalaran himself—he will not leave Booty Bay just to chat with tiresome old mages—he sends you north to have a mage look at them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_601-7e4497b6597c70ec233e/1-0000.mp3", duration = 58.9583673, start = 0},
  },
}
P.transport["quest:602"] = {
  hash = "f39bd6",
  fullHash = "f39bd6",
  text = "Magical Analysis. Baron Revilgaz directs you northward from Booty Bay to consult the Kirin Tor in Dalaran. Taking a bag of water elemental bracers, you seek out Archmage Ansirem Runeweaver to decipher the arcane curse tied to the Stone of the Tides. Following your hunt for the water elemental bracers, Baron Revilgaz hands over a bundle of their bracers. The goblin leader knows that unraveling the curse behind the Stone of the Tides requires deeper magical expertise than Booty Bay can provide. He directs you north toward the ruins of Dalaran, where the wizards remain deeply engaged in rebuilding their broken kingdom. Convinced that arcane scholars cannot ignore an intriguing puzzle, Revilgaz recommends seeking Archmage Ansirem Runeweaver directly, having had dealings with the knowledgeable wizard in the past.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_602-68ae020ef930c53732c6/1-0000.mp3", duration = 47.6212245, start = 0},
  },
}
P.transport["quest:6027"] = {
  hash = "a1ed65",
  fullHash = "a1ed65",
  text = "Book of the Ancients. Azore Aldamort of the Ethel Rethor tower trusts you with a gem. Set in the hand of a serpent statue on Ranazjar Isle, northwest of the tower, it calls up the protector of the Book of the Ancients, which holds secrets the naga have kept for centuries. After Sceptre of Light, Azore Aldamort hands you the Gem of the Serpent. A Serpent Statue stands on Ranazjar Isle, a little island to the northwest of the Ethel Rethor tower, and the gem belongs on its hand. That will bring forth the guardian of the Book of the Ancients, a book that holds naga secrets kept for centuries. Azore hopes it will teach much about their scaled foes.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6027-020808b93124ed518d9e/1-0000.mp3", duration = 38.6612245, start = 0},
  },
}
P.transport["quest:603"] = {
  hash = "bc277d",
  fullHash = "bc277d",
  text = "Ansirem's Key. Following his magical examination, Archmage Ansirem Runeweaver points toward an ancient troll dagger capable of disrupting the focal altar empowering the Stone of the Tides. He passed it long ago to his daughter Catelyn, a headstrong girl who left home for the pirates of Booty Bay. Ansirem Runeweaver determines that an altar or focal point amplifies the power of the Stone of the Tides. Overpowering that magic calls for another troll relic: an ancient dagger he found while researching in Stranglethorn. He passed it long ago to his daughter Catelyn, a headstrong girl who left home for the pirates of Booty Bay.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_603-c6d781f183a0f1321b90/1-0000.mp3", duration = 38.164898, start = 0},
  },
}
P.transport["quest:605"] = {
  hash = "4f90c5",
  fullHash = "4f90c5",
  text = "Singing Blue Shards. Crank Fizzlebub seeks an enterprising adventurer to gather Singing Crystal Shards from the basilisks of Stranglethorn Vale. Competition with the Venture Company prevents him from harvesting the mineral deposits directly, leaving basilisk hides as the next best option. He promises a cut of the profits to anyone willing to bring him ten decent specimens. Crank Fizzlebub has identified an eager market for the Singing Crystals unique to Stranglethorn Vale. Unfortunately for his business ambitions, the aggressive presence of the Venture Company makes it hard for him to gather raw crystal in the field. To circumvent his rivals, Fizzlebub turns to an alternative method: basilisks consume the crystals, incorporating the mineral into their hardened hides, which allows usable shards to be retrieved from them instead. While any basilisk in the jungle might yield acceptable crystal fragments, Fizzlebub says the gentler ones are found along the shores south of Zul'Kunda, up north. Gathering ten shards allows him to move forward with his buyers, after which his business concerns shift toward the operations of the Venture Company itself.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_605-ea5acbb9fe23308c364d/1-0000.mp3", duration = 68.4146939, start = 0},
  },
}
P.transport["quest:610"] = {
  hash = "0c31c7",
  fullHash = "0c31c7",
  text = "\"Pretty Boy\" Duncan. After tracking down Catelyn the Blade on behalf of her father, an adventurer learns that her weapon is no longer in her hands. She demands that her lost dagger be retrieved from a pirate named Pretty Boy Duncan before she cooperates further. Following the trail from Ansirem's Key leads directly to Catelyn the Blade, who ran away from a quiet life of scholarship and dusty tomes alongside mages. She cannot hand over her dagger at her father's request, since she no longer has it. If anyone hopes to secure her blade, they will first have to deal with the Bloodsail Buccaneer who took it. Catelyn suffered an uncharacteristic defeat at the hands of Pretty Boy Duncan, who struck her unconscious and made off with her signature weapon. As a fighter who relies on her personal knife, she insists on recovering that exact weapon from the buccaneer before anything else can move forward.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_610-cfe27b6571c00c3345f9/1-0000.mp3", duration = 52.3493878, start = 0},
  },
}
P.transport["quest:6132"] = {
  hash = "8119b6",
  fullHash = "8119b6",
  text = "Get Me Out of Here!. Melizza Brimbuzzle traveled into the Valley of Spears hoping to do business with the Maraudines, but they would not talk, and she fears they mean to eat her. She asks you to get her out of there; her brother Hornizz will pay you handsomely. Melizza walked into the Valley of Spears to speak with the Maraudines, thinking she could strike a deal. They would not talk, and she suspects they would rather eat her. She says she overheard centaurs only minutes ago discussing wood for their cookpot, and she wants out quickly. Hornizz Brimbuzzle waits at the family camp, east of here and beside the kodo graveyard. Melizza promises that her brother will pay you well for bringing her out of the valley.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6132-a1a844a69b824b733a8e/1-0000.mp3", duration = 40.1763265, start = 0},
  },
}
P.transport["quest:6134"] = {
  hash = "6d35e0",
  fullHash = "6d35e0",
  text = "Ghost-o-plasm Round Up. Hornizz Brimbuzzle thinks there is money in the ghosts of the Valley of Bones. He figures the Magram centaurs would pay plenty for ghost energy, and he gives you a crate of ghost magnets to draw the spirits out. Hornizz points you southeast, to the Valley of Bones, where Magram ghosts walk. It sounds frightening, he admits, but surely it is scarier still for the Magram. He is sure that ghost energy captured there would be worth plenty to those centaurs. He hands you a crate of ghost magnets. Set down between the two huge skeletons in the valley, known as the Dead Goliaths, a magnet lures the ghosts toward it. From them you take ghost-o-plasm, which is what Hornizz plans to sell to the Magram. He wants eight ghost-o-plasms brought back to him, along with the crate.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6134-9a8a828905aae30d38a9/1-0000.mp3", duration = 46.2367347, start = 0},
  },
}
P.transport["quest:6141"] = {
  hash = "d4edda",
  fullHash = "d4edda",
  text = "Brother Anton. Brother Crowley speaks of Brother Anton, a fellow warrior who learned of undead in distant Kalimdor and booked passage at once to destroy them. Anton is looking for people with bravery and resolve, and waits in Nijel's Point in Desolace. Brother Crowley says rumors of an undead infestation in Desolace, a land in far-off Kalimdor, reached Anton, who immediately booked passage to seek and destroy the menace. Anton wants help from those with bravery and resolve. If your heart is true, Crowley tells you to speak with Anton in Nijel's Point, the Alliance town in Desolace.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6141-49b44fd1d25ada8923fb/1-0000.mp3", duration = 35.9444898, start = 0},
  },
}
P.transport["quest:6142"] = {
  hash = "8eac20",
  fullHash = "8eac20",
  text = "Clam Bait. Mai'Lahii at Shadowprey Village has fished all his life and says the best bait is soft-shelled clam meat, which no fish can resist. He wants ten pieces, to be found around a wrecked ship up the coast to the north. Mai'Lahii has fished all his life, and he swears by soft-shelled clam meat as bait, since the fish cannot resist it. To the north, off the coast, lies a wrecked ship, and soft-shelled clams are scattered throughout that area. He asks for ten pieces of the meat.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6142-9aa53add5f0bfdf1f466/1-0000.mp3", duration = 31.242449, start = 0},
  },
}
P.transport["quest:6143"] = {
  hash = "0767ae",
  fullHash = "0767ae",
  text = "Other Fish to Fry. Drulzegar Skraghook, a fisherman at Shadowprey Village in Desolace, lost the entire crew to the naga while fishing near Ranazjar Isle. Guilt weighs on Drulzegar, who asks you to go after the Slitherblade. Drulzegar Skraghook and the crew fished by Ranazjar Isle, which lies north of a wreck on the coast, and had done so many times. One morning the naga attacked and killed everyone except Drulzegar. Since then revenge is all Drulzegar thinks about, and the guilt is too much to bear. Drulzegar wants seven Slitherblade Myrmidons, seven Slitherblade Naga and five Slitherblade Sorceresses slain. A bad knee keeps Drulzegar from going along. The naga, Drulzegar says, usually lurk far down among the coral reefs beneath the waves, and the effort will be rewarded.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6143-4935520da720e5e86416/1-0000.mp3", duration = 50.964898, start = 0},
  },
}
P.transport["quest:616"] = {
  hash = "9faea8",
  fullHash = "9faea8",
  text = "The Haunted Isle. Krazek keeps his ears open for unusual rumors throughout Booty Bay on behalf of Baron Revilgaz. A tale shared by tavern sailors speaks of a haunted island off the coast, inhabited by water elementals and the ghost of a raving goblin. Delivering this rumor to Revilgaz piques the baron's interest in an ancient troll legend. In the bustling port of Booty Bay, Krazek gathers word of anything unusual happening throughout Stranglethorn Vale at the request of Baron Revilgaz. While Krazek normally pays little heed to spectral gossip, stories told by sailors drinking in the local tavern caught his attention. They speak of an offshore isle occupied by water elementals and haunted by a raving goblin ghost, so he asks you to relay the story to the baron. Upon hearing Krazek's report of the haunted isle, Baron Revilgaz recalls an old troll legend he once read about in a book. The presence of water elementals and the goblin apparition leads the baron to suspect that an ancient relic, the Stone of the Tides, might finally be within his grasp to add to his personal collection of artifacts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_616-c0346f88d626b926ea4f/1-0000.mp3", duration = 66.0636735, start = 0},
  },
}
P.transport["quest:6161"] = {
  hash = "ec3369",
  fullHash = "ec3369",
  text = "Claim Rackmore's Treasure!. Rackmore's log tells of a ship bound for Feathermoon Stronghold that was set upon by creatures of the sea. To keep his treasure from his enemies, Rackmore hid the chest on Ranazjar Isle, and the silver key and golden key that open it are lost. The log says Rackmore's ship was on its way to Feathermoon Stronghold when seafaring creatures attacked it. Hoping to keep his treasure from his enemies, he hid the chest on Ranazjar Isle. Two keys open it, one silver and one gold, and both were lost. Someone who finds the keys and the chest will find a treasure.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6161-a2fc955162217f132d1a/1-0000.mp3", duration = 34.324898, start = 0},
  },
}
P.transport["quest:627"] = {
  hash = "9adb5a",
  fullHash = "9adb5a",
  text = "Favor for Krazek. While repairing a crock pot brought down to Booty Bay, the goblin Krazek demands a personal favor in return. He wants rare lesser bloodstone ore retrieved from a distant cave in the northern hills before he will hand back the repaired cookware. After accepting the broken cookware in Booty Bay, Krazek pauses his tinkering to ask for a trade. Rather than repairing the pot for free, he directs you far northward into the Arathi Highlands. Within a cave in Drywhisker Gorge lies lesser bloodstone ore, a low-grade yet prized mineral sought after by those who understand its properties. Krazek promises to work on fixing the pot while you make the long journey north. He expects four loads of the bloodstone brought back to the port, offering payment in exchange for the favor if you return with enough samples. He also makes it clear that if you lack the knowledge to extract the ore yourself, you will need to rely on someone who does.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_627-5d85637f36e38553280a/1-0000.mp3", duration = 56.7379592, start = 0},
  },
}
P.transport["quest:629"] = {
  hash = "59fa8b",
  fullHash = "59fa8b",
  text = "The Vile Reef. Kin'weelay at Grom'gol Base Camp seeks a piece of an ancient stone tablet resting deep beneath the Savage Coast. The sunken city, known as the Vile Reef, is infested with aggressive murlocs and holds the legendary history of Gri'lek, which the Darkspear tribe wishes to preserve in Orgrimmar. Northwest of Grom'gol Base Camp, an ancient troll city slipped beneath the waters along the Savage Coast when a violent earthquake shattered the land long ago. Now referred to as the Vile Reef, its flooded ruins crawl with hostile murlocs that assault anyone venturing near. Resting on the sea floor among the ruins is a massive stone tablet carved with the story of Gri'lek, a legendary troll hero whose memory remains sacred to the Darkspear. Because the full monument is far too massive to carry away from the depths, Kin'weelay asks you to break off a shard from the stone. He intends to carry this fragment back to Orgrimmar, enshrining it in a sacred place so the Darkspear will never forget the strength and honor of Gri'lek.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_629-0e8d60f8fb3fdff257d0/1-0000.mp3", duration = 64.7836735, start = 0},
  },
}
P.transport["quest:635"] = {
  hash = "7f2b42",
  fullHash = "7f2b42",
  text = "Crystal in the Mountains. The Pendant of Myzrael pulses in your hand and a pleading reaches you, as if someone desperately needs help. A vision shows a gleaming crystal rising out of the ground in the northern mountains of Arathi, and you feel drawn to that place. The pendant pulses as you hold it. From it comes a sense of pleading, as if someone is trying to reach you and badly needs your help. Then a vision opens before you: the mountains in the north of Arathi, and a gleaming crystal thrusting up out of the ground. You feel drawn to that place.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_635-cb8dec2f39d1a70ca9b1/1-0000.mp3", duration = 30.6416327, start = 0},
  },
}
P.transport["quest:638"] = {
  hash = "090abc",
  fullHash = "090abc",
  text = "Trollbane. Vol'jin has ordered the Darkspear trolls to recover the ancient sword Trol'kalar from the ruined human kingdom of Stromgarde. With King Thoras Trollbane fallen, the blade is meant to serve the Horde in future conflicts against the trolls of Zul'Gurub. Following the death of King Thoras Trollbane and the collapse of Stromgarde into ruin, Chieftain Vol'jin has ordered that every effort be made to spirit Trol'kalar away. This storied blade has long rested in human hands, but the Darkspear tribe hopes to claim it for the battles looming against the jungle trolls dwelling within Zul'Gurub. To carry out Vol'jin's directive, a seasoned hunter named Zengu was sent to the Horde outpost of Hammerfall, situated in the northeastern reaches of the Arathi Highlands. Nimboya directs travelers from Stranglethorn Vale to seek out Zengu and assist in securing the legendary weapon.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_638-c22eccc861792ea28fad/1-0000.mp3", duration = 50.7297959, start = 0},
  },
}
P.transport["quest:639"] = {
  hash = "4db1a7",
  fullHash = "4db1a7",
  text = "Sigil of Strom. Zengu in Hammerfall wants the sigils that guard Trol'kalar, the sword of Lord Ignaeus Trollbane. The first, the Sigil of Strom, was taken by the Syndicate, and a Syndicate agent in Stromgarde is likely to hold it. In ancient times the trolls fought the Arathorian Empire, and their ablest foe was Lord Ignaeus of Strom, called Trollbane. He went into battle wielding Trol'kalar, a name that means troll slayer in the trolls' old tongue. Now Trollbane's sons are weakened and their stronghold lies in ruins. Several sigils protect the sword, and the survivors of Stromgarde each took a share of them. Zengu says they must all be retrieved. The Syndicate seized the first, and Zengu reckons one of their agents in Stromgarde has it. Bring it back to him at Hammerfall.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_639-6928047831c42f50396d/1-0000.mp3", duration = 49.4497959, start = 0},
  },
}
P.transport["quest:657"] = {
  hash = "bb5704",
  fullHash = "bb5704",
  text = "Hints of a New Plague?. Quae has gone through the folder and learned that Apothecary Jorell is running deadly experiments at Go'Shek Farm. Quae is in poor shape after clashing with orcs and cannot help Kinelory, who will need your protection when she heads for the farm to steal any of Jorell's research not yet sent to Tarren Mill. Quae reads through the folder and finds that Apothecary Jorell is running deadly experiments at Go'Shek Farm. How that touches Hillsbrad is unclear to Quae, yet Phin would not want it to go on. Some of Jorell's research has already been sent to Tarren Mill. While you were away, Quae clashed with some orcs and is in no shape to help Kinelory. Kinelory means to go down to the farm and steal the research Jorell has not yet sent to Tarren Mill, and she will need protection. You are to speak to Kinelory.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_657-26779bb5918451852471/1-0000.mp3", duration = 49.0579592, start = 0},
  },
}
P.transport["quest:658"] = {
  hash = "6f90c5",
  fullHash = "6f90c5",
  text = "Hints of a New Plague?. Quae and Kin have been watching Go'Shek Farm for days. Kin saw a courier come out of a small house to the south, and they suspect the courier carries notes bound for Tarren Mill. Quae wants those documents and asks whether you are a skilled tracker. Quae is not surprised that Phin Odelic sent you to check on them, since Phin worries too much. Quae and Kin have been watching the farm for days. Not long ago Kin saw a courier come out of a small house to the south. Kin talks a lot, but Quae can always trust Kin's senses in dangerous areas. Quae asks whether you are a skilled tracker. The courier may carry notes bound for Tarren Mill, and getting hold of those documents could shed some light on what is happening in Hillsbrad. You are to find the Forsaken Courier and bring her Sealed Folder back to Quae near Go'Shek Farm. While you search, Kin spots an apothecary leaving that same house. Quae is confident the apothecary is up to no good, but needs proof before anyone does something rash.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_658-534b277174ce9889040d/1-0000.mp3", duration = 60.7085714, start = 0},
  },
}
P.transport["quest:659"] = {
  hash = "d47460",
  fullHash = "d47460",
  text = "Hints of a New Plague?. Phin Odelic leads a band of adventurers looking into odd happenings in the area, and believes the undead are involved. Two companions, Quae and Kinelory, headed for Go'Shek Farm, in the Arathi Highlands. No word has come from them for days. Not long ago, a cousin of Phin's in Hillsbrad had to put down his dog, Stanley. The beast had mystically swollen to a huge size and savagely turned on anyone who came near. Phin believes the undead are involved in the odd happenings, and the group is looking for signs to prove it. Quae and Kinelory, two of Phin's companions, headed into the Arathi Highlands, to Go'Shek Farm, and have not checked in for days. Phin grows concerned and wants you to find them near the farm.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_659-37cd9a94660f6ba32ba5/1-0000.mp3", duration = 44.9306122, start = 0},
  },
}
P.transport["quest:660"] = {
  hash = "05c5b3",
  fullHash = "05c5b3",
  text = "Hints of a New Plague?. Kinelory is ready to head down to the farm and wants you at her side. She fears the undead may be doing harm back in Hillsbrad the longer they wait, and you are asked to see her safely back to Quae. After the earlier steps of the investigation, Kinelory is ready to act. She asks you to come with her down to the farm. You are to see her safely back to Quae, and anyone who cares about the people of Hillsbrad is urged to protect her.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_660-765ee6ed8fdde9df7c12/1-0000.mp3", duration = 26.8277551, start = 0},
  },
}
P.transport["quest:661"] = {
  hash = "27548d",
  fullHash = "27548d",
  text = "Hints of a New Plague?. Kinelory is back from the farm, none the worse for wear, and Quae has the items she brought. Quae and Kinelory mean to stay in Arathi a while longer, so it falls to you to carry word to Phin Odelic in Southshore. Quae is pleased with how well you looked after Kinelory, who has come back in better shape than after a night at the tavern. The items from the farm should give Phin Odelic some idea of what is happening out in Arathi. Since the farm was attacked, Quae and Kinelory plan to stay put a little longer in case of retaliation, and ask you to go back to Southshore and speak to Phin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_661-94d3bd7bbbfb4c1652f5/1-0000.mp3", duration = 34.8212245, start = 0},
  },
}
P.transport["quest:663"] = {
  hash = "9f32fa",
  fullHash = "9f32fa",
  text = "Land Ho!. At Faldir's Cove, the lookout Lolo greets you with news that Captain O'Breen's stop here will last far longer than planned. Two ships of the formation, the Spirit of Silverpine and the Maiden's Folly, are lost, and Lolo suggests you speak with the captain. Lolo, ever on the lookout, spots you arriving at Faldir's Cove. Captain O'Breen had promised the crew only a few hours here, time enough to collect the treasure and head back to Booty Bay. Lolo doubts it will be so quick. Two ships of the formation, the Spirit of Silverpine and the Maiden's Folly, now rest on the bottom of the sea. Anyone who means to stay is told to talk to the captain.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_663-371050e13edc8aebc399/1-0000.mp3", duration = 43.1281633, start = 0},
  },
}
P.transport["quest:681"] = {
  hash = "f3080c",
  fullHash = "f3080c",
  text = "Northfold Manor. Captain Nials, at Refuge Pointe, asks for help against the Syndicate holding Northfold Manor. Their hold on the land between the defenders of Stromgarde and Southshore makes it hard for supplies to arrive. Stromgarde has been carved up between the ogres, the Syndicate and the Alliance, and every faction fights the others to a bloody stalemate. The Alliance's forces dwindle while their enemies grow. The defenders need help from Southshore, but supplies are slow to arrive. The Syndicate holds the ground between the defenders and Southshore. Captain Nials wants you to go to their base at Northfold Manor and cut down their highwaymen and mercenaries, in the hope that the pressure on the supply trains eases and more get through.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_681-9aef43b0a84301141da5/1-0000.mp3", duration = 44.0946939, start = 0},
  },
}
P.transport["quest:691"] = {
  hash = "4fa24e",
  fullHash = "4fa24e",
  text = "Worth Its Weight in Gold. At Refuge Pointe, Apprentice Kryten is after Witherbark tusks, medicine pouches and a shadow hunter's knife, all reagents for Archmage Malin, who sent him and Skuerto to gather them. He asks you to seek them among the Witherbark trolls in the southeast of Arathi. Archmage Malin sent Kryten and Skuerto to Arathi to collect reagents, and Kryten had no idea how to gather them until you arrived. He needs ten Witherbark tusks, four medicine pouches and one shadow hunter knife. The Witherbark trolls make their home in the southeast of Arathi. By Kryten's research, any Witherbark troll should have tusks, and the witch doctors carry the medicine pouches. The knife belongs to the mightiest shadow hunters, handed to them after they finish their rites of passage. Only battle will show which of them has one.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_691-be475b0fefd56669554b/1-0000.mp3", duration = 49.7632653, start = 0},
  },
}
P.transport["quest:693"] = {
  hash = "2de040",
  fullHash = "2de040",
  text = "Wand over Fist. Skuerto at Refuge Pointe has worked out where the first of Trelane's items ended up. Kor'gresh has Trelane's Wand of Invocation in Boulderfist Hall, and Skuerto wants it brought back. After your work for Apprentice Kryten, Skuerto has found where Trelane's first item went. Kor'gresh holds it in Boulderfist Hall, and has been throwing blasts of ice at his own kin to keep them in line. Skuerto reckons the ogre must be close to figuring out all of the wand's powers. Boulderfist Hall lies south of Refuge Pointe and then east of Thandol Span.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_693-094049bd4828911766af/1-0000.mp3", duration = 33.6979592, start = 0},
  },
}
P.transport["quest:694"] = {
  hash = "9ae7f7",
  fullHash = "9ae7f7",
  text = "Trelane's Defenses. With the wand in hand, Skuerto turns to the ogres that surround the Tower of Arathor. To bring the tower's defenses to life, he needs an azure agate from the Boulderfist shaman, to be taken to Apprentice Kryten at Refuge Pointe. Ogres surround the Tower of Arathor in Stromgarde. Skuerto says the tower's defenses must be activated if you are to stand a chance against them and still reach the items alive. Certain gems from the tower have caught the fancy of the Boulderfist shaman, who carried them off, though Skuerto says they will not keep them for long. Bring one azure agate to Apprentice Kryten at Refuge Pointe, who knows the spell to enchant it so that it works as a key.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_694-329b9133531b6a880286/1-0000.mp3", duration = 42.1877551, start = 0},
  },
}
P.transport["quest:695"] = {
  hash = "d3328a",
  fullHash = "d3328a",
  text = "An Apprentice's Enchantment. Apprentice Kryten has enchanted the agate you brought him from the Boulderfist shaman. Touched to a pedestal at the foot of the tower, it will wake the tower's defenses. Before you leave, he sends you to Skuerto for the rest. Kryten hands you the enchanted gem. He explains that touching it to a pedestal at the foot of the tower will wake the tower's defenses, and that you should use it when you are ready to go in after the rest of Trelane's items. He will await your return at the camp. First, speak to Skuerto, who will fill in whatever else you need to know.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_695-6d29073c862dc07d5d71/1-0000.mp3", duration = 35.0563265, start = 0},
  },
}
P.transport["quest:696"] = {
  hash = "62a4cc",
  fullHash = "62a4cc",
  text = "Attack on the Tower. With the tower's defenses awake, Skuerto at Refuge Pointe sends you into the ogre-held tower for Trelane's phylactery, orb and ember agate. They should lie in chests inside, and Skuerto says Malin will be more than pleased if you bring them back. After Kryten's enchantment, Skuerto tells you what to look for: Trelane's phylactery, orb and ember agate. The three should be sitting in chests inside the tower, and you should have no trouble opening them yourself, though the ogres call for care. The tower's defenses will not deal with them on their own, and if the ogres find you stealing from them, they will put the hurt on you.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_696-9fe441c1208e9514529e/1-0000.mp3", duration = 37.9297959, start = 0},
  },
}
P.transport["quest:697"] = {
  hash = "d67cc0",
  fullHash = "d67cc0",
  text = "Malin's Request. Skuerto gives you a sealed letter for Archmage Malin, who is found in Stormwind's Mage Quarter. It tells Malin that Kryten and Skuerto will be home soon, and Skuerto is certain Malin will repay you well for helping them in Arathi. After the work in Arathi, Skuerto hands you a letter to take back to Stormwind. Its message for Archmage Malin in the Mage Quarter is that Kryten and Skuerto will be home soon. Skuerto has no doubt that Malin will repay you well for helping them, and sends you off with a wish for a safe journey.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_697-0eaa629c58f0fbeb3aaf/1-0000.mp3", duration = 31.8432653, start = 0},
  },
}
P.transport["quest:702"] = {
  hash = "80dcff",
  fullHash = "80dcff",
  text = "Guile of the Raptor. After the earlier Guile of the Raptor, Tor'gan hands you an orb and sends you to Gor'mul at Hammerfall. Its energy carries the essence of the raptor, meant to stir Gor'mul's spirit and give him new purpose. Tor'gan gives you an orb whose energy is meant to fill Gor'mul with the raptor's essence. He hopes it will rouse the warrior's spirit and set him on a fresh course in life. Once Gor'mul is himself again, Tor'gan means to explain the current state of the Horde to him and gain a great warrior's help in the unceasing battles. Gor'mul greets your return with sourness, saying he wants nothing more than more of Tor'gan's pity and mocking you with talk of brightly colored string.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_702-337153819aa2db604176/1-0000.mp3", duration = 40.0979592, start = 0},
  },
}
P.transport["quest:847"] = {
  hash = "4dc9e1",
  fullHash = "4dc9e1",
  text = "Guile of the Raptor. After Tor'gan's orb gave Gor'mul the raptor's essence, the power he felt has him wondering about the shamans' magic. He sends you to tell Tor'gan he has been convinced, for the time being, and will listen. Gor'mul wonders aloud whether the power coursing through him is the shamans' power that Tor'gan tried to show him. He finds it interesting. He asks you to tell Tor'gan that he has been convinced, for the time being, and will hear what Tor'gan has to say.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_847-a48ae65be18d097d0fd7/1-0000.mp3", duration = 27.402449, start = 0},
  },
}
P.transport["quest:98071"] = {
  hash = "cc0ba0",
  fullHash = "cc0ba0",
  text = "Brewer's Trade. A trade has been worked out with the Dun Garok brew-kin, who miss the Fallrook family's vineyards as much as anyone. A case of Fallrook Varietal travels to their fort in the southeast of Hillsbrad Foothills, and a sack of their Homebrew Hops comes back. Most of the best bottled years of Fallrook wine are long since drunk, but cases of the Fallrook Varietal still sit in the cellars. The Dun Garok brew-kin miss the vineyards of the Fallrook family too, and a trade has been worked out with them. The case goes southeast to Dun Garok, to be left with the brew-kin beside the fireplace where they gather, down at the base of their fort. In return, you carry a sack of their Homebrew Hops back.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98071-73a21765d5312f487706/1-0000.mp3", duration = 40.6465306, start = 0},
  },
}
P.transport["quest:98463"] = {
  hash = "e9901a",
  fullHash = "e9901a",
  text = "Talk of the Town. A friendly barkeep points travelers eager for a livelier gathering toward the port of Booty Bay in Stranglethorn Vale. Those looking for wilder company are directed to seek out Nixxrax Fillamug at the Salty Sailor Tavern. Word passes quickly between drink-servers and their patrons, and news travels far beyond the local counter. A friendly bartender passes along a tip about where the genuine commotion is brewing, pointing anyone searching for wilder spectacles toward the port of Booty Bay. The destination is the Salty Sailor Tavern, a lively establishment maintained by goblins amidst the bustle of Stranglethorn Vale. There, Nixxrax Fillamug keeps cups topped up for anyone who walks in.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98463-4d4a549cc004aee6307d/1-0000.mp3", duration = 44.8, start = 0},
  },
}
